import { ISkillCard, SkillCardContext } from '../ISkillCard.ts';

export class DiamondHandsCard implements ISkillCard {
  public readonly id = 'DIAMOND_HANDS';
  public readonly title = '鑽石手冷錢包';
  public readonly badge = '信仰質押';
  public readonly category = 'STATS';
  public readonly iconKey = 'diamond';
  public readonly maxLevel = 8;
  public readonly financeTerm = '【鑽石手 (Diamond Hands)】在劇烈市場波動中長線持幣、堅不拋售的堅定投資者。';

  public getDescription(currentLevel: number): string {
    const next = currentLevel + 1;
    return `生命上限 +30 並立即回滿，恆定減傷率提高至 ${(Math.min(35, next * 5))}%`;
  }

  public isEligible(context: SkillCardContext): boolean {
    const current = context.engine.skillLevels?.get(this.id) ?? 0;
    return current < this.maxLevel;
  }

  public apply(context: SkillCardContext, _nextLevel: number): void {
    context.engine.maxHp = (context.engine.maxHp || 100) + 30;
    context.engine.hp = context.engine.maxHp;
    context.engine.damageReduction = Math.min(0.35, (context.engine.damageReduction || 0) + 0.1);
    context.callbacks?.onHpChange?.(context.engine.hp, context.engine.maxHp);
  }
}
