import * as THREE from 'three';
import { GLTFModelLoader } from '../../../games/dungeon3d/core/GLTFModelLoader.ts';

export const TELEKINETIC_MUZZLE_OFFSET = {
  x: 0.88,
  y: 2.02,
  z: 0.15,
} as const;

export class TelekineticWeaponMount3D {
  public orbitGroup: THREE.Group;
  public modelHolder: THREE.Group;
  public psychicOuterRing: THREE.Mesh;
  public psychicInnerRing: THREE.Mesh;
  private activeModelUrl: string = '';

  constructor(parentGroup: THREE.Group) {
    this.orbitGroup = new THREE.Group();
    this.orbitGroup.position.set(
      TELEKINETIC_MUZZLE_OFFSET.x,
      TELEKINETIC_MUZZLE_OFFSET.y,
      TELEKINETIC_MUZZLE_OFFSET.z
    );
    parentGroup.add(this.orbitGroup);

    // Outer purple psychic ring
    const outerRingGeo = new THREE.RingGeometry(0.34, 0.44, 24);
    const outerRingMat = new THREE.MeshBasicMaterial({
      color: 0xd500f9,
      transparent: true,
      opacity: 0.72,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    this.psychicOuterRing = new THREE.Mesh(outerRingGeo, outerRingMat);
    this.psychicOuterRing.rotation.x = -Math.PI / 2 + 0.25;
    this.psychicOuterRing.position.y = -0.14;
    this.orbitGroup.add(this.psychicOuterRing);

    // Inner cyan telekinetic core ring
    const innerRingGeo = new THREE.RingGeometry(0.18, 0.26, 18);
    const innerRingMat = new THREE.MeshBasicMaterial({
      color: 0x00e5ff,
      transparent: true,
      opacity: 0.65,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    this.psychicInnerRing = new THREE.Mesh(innerRingGeo, innerRingMat);
    this.psychicInnerRing.rotation.x = -Math.PI / 2 + 0.25;
    this.psychicInnerRing.position.y = -0.12;
    this.orbitGroup.add(this.psychicInnerRing);

    this.modelHolder = new THREE.Group();
    this.modelHolder.position.set(0, 0, 0);
    this.orbitGroup.add(this.modelHolder);
  }

  public loadWeaponModel(modelUrl: string): void {
    this.activeModelUrl = modelUrl;
    GLTFModelLoader.getInstance()
      .load(modelUrl)
      .then((gltf) => {
        if (this.activeModelUrl !== modelUrl) return;
        const { scene: model } = GLTFModelLoader.getInstance().instantiate(gltf);
        model.scale.setScalar(1.15);
        model.traverse((child) => {
          if (child instanceof THREE.Mesh && child.material) {
            const mat = child.material as THREE.MeshStandardMaterial;
            if (mat.map) {
              mat.map.colorSpace = THREE.SRGBColorSpace;
            }
          }
        });
        while (this.modelHolder.children.length > 0) {
          this.modelHolder.remove(this.modelHolder.children[0]);
        }
        this.modelHolder.add(model);
      })
      .catch(() => {
        // Ignore in headless test environment
      });
  }

  public aimAtDirection(dx: number, dz: number): void {
    this.orbitGroup.rotation.y = Math.atan2(dx, dz);
  }

  public update(
    delta: number,
    walkTime: number,
    isFiring: boolean = false,
    fireProgress: number = 0
  ): void {
    this.psychicOuterRing.rotation.z += delta * 2.6;
    this.psychicInnerRing.rotation.z -= delta * 4.2;

    const hoverY = Math.sin(walkTime * 1.4) * 0.08;
    const hoverTilt = Math.cos(walkTime * 1.1) * 0.06;

    if (isFiring) {
      const kick = Math.sin(fireProgress * Math.PI);
      this.orbitGroup.position.set(
        TELEKINETIC_MUZZLE_OFFSET.x,
        TELEKINETIC_MUZZLE_OFFSET.y + hoverY + kick * 0.07,
        TELEKINETIC_MUZZLE_OFFSET.z
      );
      this.modelHolder.position.set(0, 0, -kick * 0.24);
      this.modelHolder.rotation.x = -kick * 0.32;
      this.psychicOuterRing.scale.setScalar(1.0 + kick * 0.35);
      this.psychicInnerRing.scale.setScalar(1.0 + kick * 0.45);
    } else {
      this.orbitGroup.position.set(
        TELEKINETIC_MUZZLE_OFFSET.x,
        TELEKINETIC_MUZZLE_OFFSET.y + hoverY,
        TELEKINETIC_MUZZLE_OFFSET.z
      );
      this.modelHolder.position.set(0, 0, 0);
      this.modelHolder.rotation.x = hoverTilt;
      const ringPulse = 0.94 + Math.sin(walkTime * 2.2) * 0.08;
      this.psychicOuterRing.scale.setScalar(ringPulse);
      this.psychicInnerRing.scale.setScalar(1.0 / ringPulse);
    }
  }
}
