export interface Vector2D {
  x: number;
  y: number;
}

export class TouchJoystick {
  private activeTouchId: number | null = null;
  private originX: number = 0;
  private originY: number = 0;
  private currentX: number = 0;
  private currentY: number = 0;
  private isPointerDown: boolean = false;
  private radius: number = 55;

  private vector: Vector2D = { x: 0, y: 0 };
  private keyState: Record<string, boolean> = {};

  private containerEl: HTMLElement | null = null;
  private baseEl: HTMLElement | null = null;
  private knobEl: HTMLElement | null = null;

  constructor() {
    this.initKeyboardListeners();
  }

  public attach(container: HTMLElement): void {
    this.containerEl = container;
    this.createDomElements();
    this.initTouchListeners(container);
  }

  private createDomElements(): void {
    if (!this.containerEl) return;

    this.baseEl = document.createElement('div');
    this.baseEl.className = 'dungeon3d-joystick-base';
    this.baseEl.style.cssText = `
      position: absolute;
      width: ${this.radius * 2}px;
      height: ${this.radius * 2}px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.12);
      border: 2px solid rgba(0, 230, 118, 0.5);
      box-shadow: 0 0 15px rgba(0, 230, 118, 0.2);
      pointer-events: none;
      transform: translate(-50%, -50%);
      display: none;
      z-index: 40;
    `;

    this.knobEl = document.createElement('div');
    this.knobEl.className = 'dungeon3d-joystick-knob';
    this.knobEl.style.cssText = `
      position: absolute;
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: radial-gradient(circle, #00e676 0%, #00b248 100%);
      box-shadow: 0 0 12px rgba(0, 230, 118, 0.7);
      pointer-events: none;
      transform: translate(-50%, -50%);
      display: none;
      z-index: 41;
    `;

    this.containerEl.appendChild(this.baseEl);
    this.containerEl.appendChild(this.knobEl);
  }

  private initTouchListeners(container: HTMLElement): void {
    const handleStart = (clientX: number, clientY: number, touchId: number | null) => {
      // Only trigger joystick in the lower 75% of the screen
      const rect = container.getBoundingClientRect();
      const relativeY = clientY - rect.top;
      if (relativeY < rect.height * 0.25) return;

      this.isPointerDown = true;
      this.activeTouchId = touchId;
      this.originX = clientX - rect.left;
      this.originY = clientY - rect.top;
      this.currentX = this.originX;
      this.currentY = this.originY;

      if (this.baseEl && this.knobEl) {
        this.baseEl.style.left = `${this.originX}px`;
        this.baseEl.style.top = `${this.originY}px`;
        this.baseEl.style.display = 'block';

        this.knobEl.style.left = `${this.originX}px`;
        this.knobEl.style.top = `${this.originY}px`;
        this.knobEl.style.display = 'block';
      }

      this.updateVector();
    };

    const handleMove = (clientX: number, clientY: number, touchId: number | null) => {
      if (!this.isPointerDown) return;
      if (touchId !== null && this.activeTouchId !== touchId) return;

      const rect = container.getBoundingClientRect();
      this.currentX = clientX - rect.left;
      this.currentY = clientY - rect.top;

      let dx = this.currentX - this.originX;
      let dy = this.currentY - this.originY;
      const dist = Math.hypot(dx, dy);

      if (dist > this.radius) {
        dx = (dx / dist) * this.radius;
        dy = (dy / dist) * this.radius;
      }

      if (this.knobEl) {
        this.knobEl.style.left = `${this.originX + dx}px`;
        this.knobEl.style.top = `${this.originY + dy}px`;
      }

      this.updateVector();
    };

    const handleEnd = (touchId: number | null) => {
      if (touchId !== null && this.activeTouchId !== touchId) return;

      this.isPointerDown = false;
      this.activeTouchId = null;
      this.vector = { x: 0, y: 0 };

      if (this.baseEl && this.knobEl) {
        this.baseEl.style.display = 'none';
        this.knobEl.style.display = 'none';
      }
    };

    container.addEventListener(
      'touchstart',
      (e) => {
        if (e.target instanceof HTMLButtonElement || e.target instanceof HTMLAnchorElement) return;
        if (e.touches.length > 0) {
          const t = e.touches[0];
          handleStart(t.clientX, t.clientY, t.identifier);
        }
      },
      { passive: true }
    );

    container.addEventListener(
      'touchmove',
      (e) => {
        for (let i = 0; i < e.touches.length; i++) {
          const t = e.touches[i];
          if (t.identifier === this.activeTouchId) {
            handleMove(t.clientX, t.clientY, t.identifier);
            break;
          }
        }
      },
      { passive: true }
    );

    container.addEventListener('touchend', (e) => {
      if (this.activeTouchId !== null) {
        let stillActive = false;
        for (let i = 0; i < e.touches.length; i++) {
          if (e.touches[i].identifier === this.activeTouchId) {
            stillActive = true;
            break;
          }
        }
        if (!stillActive) handleEnd(this.activeTouchId);
      }
    });

    container.addEventListener('touchcancel', () => handleEnd(null));
    window.addEventListener('touchend', () => {
      if (!this.isPointerDown) return;
      handleEnd(null);
    });
    window.addEventListener('touchcancel', () => handleEnd(null));
    window.addEventListener('blur', () => this.resetControls());

    // Pointer events for mouse click & drag on desktop
    container.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'touch') return; // Handled by touch events
      if (e.target instanceof HTMLButtonElement || e.target instanceof HTMLAnchorElement) return;
      handleStart(e.clientX, e.clientY, null);
    });

    window.addEventListener('pointermove', (e) => {
      if (e.pointerType === 'touch') return;
      handleMove(e.clientX, e.clientY, null);
    });

    window.addEventListener('pointerup', (e) => {
      if (e.pointerType === 'touch') return;
      handleEnd(null);
    });
  }

  private initKeyboardListeners(): void {
    window.addEventListener('keydown', (e) => {
      this.keyState[e.key.toLowerCase()] = true;
    });

    window.addEventListener('keyup', (e) => {
      this.keyState[e.key.toLowerCase()] = false;
    });

    window.addEventListener('blur', () => this.resetControls());
  }

  private updateVector(): void {
    const dx = this.currentX - this.originX;
    const dy = this.currentY - this.originY;
    const dist = Math.hypot(dx, dy);

    if (dist < 8) {
      this.vector = { x: 0, y: 0 };
    } else {
      const scale = Math.min(1.0, dist / this.radius);
      this.vector = {
        x: (dx / dist) * scale,
        y: (dy / dist) * scale,
      };
    }
  }

  public getVector(): Vector2D {
    // 1. If joystick is currently touched/dragged, prioritize it
    if (this.isPointerDown && (this.vector.x !== 0 || this.vector.y !== 0)) {
      return this.vector;
    }

    // 2. Otherwise fall back to keyboard controls
    let kx = 0;
    let ky = 0;

    if (this.keyState['w'] || this.keyState['arrowup']) ky -= 1;
    if (this.keyState['s'] || this.keyState['arrowdown']) ky += 1;
    if (this.keyState['a'] || this.keyState['arrowleft']) kx -= 1;
    if (this.keyState['d'] || this.keyState['arrowright']) kx += 1;

    const len = Math.hypot(kx, ky);
    if (len > 0) {
      return { x: kx / len, y: ky / len };
    }

    return { x: 0, y: 0 };
  }

  public isMoving(): boolean {
    const v = this.getVector();
    return Math.hypot(v.x, v.y) > 0.15;
  }

  /**
   * 規格書 12 (2.2)：強制重設搖桿與按鍵狀態至 (0, 0)，防止復活或切換場景時移動死鎖
   */
  public resetControls(): void {
    this.isPointerDown = false;
    this.activeTouchId = null;
    this.vector = { x: 0, y: 0 };
    this.keyState = {};
    if (this.baseEl && this.knobEl) {
      this.baseEl.style.display = 'none';
      this.knobEl.style.display = 'none';
    }
  }

  public destroy(): void {
    this.resetControls();
    if (this.baseEl && this.baseEl.parentElement) {
      this.baseEl.parentElement.removeChild(this.baseEl);
    }
    if (this.knobEl && this.knobEl.parentElement) {
      this.knobEl.parentElement.removeChild(this.knobEl);
    }
  }
}
