import { I18nService } from '../../../platform/I18nService.ts';
import { SkillCardRegistry } from '../skills/SkillCardRegistry.ts';
import { getSurvivorSvg } from '../data/icons.ts';

export interface PlayerStatusModalOptions {
  onResume: () => void;
}

export class PlayerStatusModal {
  private options: PlayerStatusModalOptions;
  private element: HTMLElement | null = null;
  private currentEngine: any = null;
  private unsubscribeLocale: (() => void) | null = null;

  constructor(options: PlayerStatusModalOptions) {
    this.options = options;
  }

  public render(): HTMLElement {
    const modalEl = document.createElement('div');
    modalEl.id = 'player-status-modal';
    modalEl.className = 'modal-overlay player-status-overlay';
    modalEl.style.display = 'none';

    // Touch and pointer isolation to prevent touch slipping through to canvas joystick
    modalEl.addEventListener('touchstart', (e) => {
      e.stopPropagation();
    }, { passive: true });
    modalEl.addEventListener('touchmove', (e) => {
      e.stopPropagation();
    }, { passive: true });
    modalEl.addEventListener('touchend', (e) => {
      e.stopPropagation();
    }, { passive: true });
    modalEl.addEventListener('pointerdown', (e) => {
      e.stopPropagation();
    });

    this.element = modalEl;

    const i18n = I18nService.getInstance();
    if (this.unsubscribeLocale) {
      this.unsubscribeLocale();
    }
    this.unsubscribeLocale = i18n.onLocaleChange(() => {
      if (this.isActive() && this.currentEngine) {
        this.updateContent(this.currentEngine);
      }
    });

    return modalEl;
  }

  public show(engine: any): void {
    this.currentEngine = engine;
    if (!this.element) {
      this.render();
    }
    this.updateContent(engine);
    if (this.element) {
      this.element.style.display = 'flex';
      this.element.classList.add('active');
    }
  }

  public hide(): void {
    if (this.element) {
      this.element.style.display = 'none';
      this.element.classList.remove('active');
    }
  }

  public isActive(): boolean {
    return this.element !== null && this.element.classList.contains('active');
  }

  public destroy(): void {
    if (this.unsubscribeLocale) {
      this.unsubscribeLocale();
      this.unsubscribeLocale = null;
    }
    if (this.element && this.element.parentNode) {
      this.element.parentNode.removeChild(this.element);
    }
    this.element = null;
    this.currentEngine = null;
  }

  private updateContent(engine: any): void {
    if (!this.element) return;
    const i18n = I18nService.getInstance();

    const hp = Math.ceil(engine.hp ?? 100);
    const maxHp = engine.maxHp ?? 100;
    const damagePct = Math.round(((engine.damageMultiplier ?? 1.0) - 1.0) * 100);
    const damageText = damagePct >= 0 ? `+${damagePct}%` : `${damagePct}%`;
    const speedVal = (engine.speed ?? 2.4).toFixed(1);
    const defensePct = Math.round((engine.damageReduction ?? 0) * 100);
    const magnetRad = `${Math.round(engine.magnetRadius ?? 65)} px`;
    const critPct = `${Math.round((engine.critChance ?? 0) * 100)}%`;
    const hpRegen = `+${engine.hpRegenRate ?? 0} / 3s`;
    const kills = `${engine.kills ?? 0}`;
    const totalSec = Math.floor(engine.elapsedTime ?? 0);
    const mins = Math.floor(totalSec / 60);
    const secs = totalSec % 60;
    const timeFormatted = `${mins}:${secs < 10 ? '0' : ''}${secs}`;

    const acquired = SkillCardRegistry.getInstance().getAcquiredCards(engine);

    let skillsHtml = '';
    if (acquired.length === 0) {
      skillsHtml = `<div class="status-empty-skills">${i18n.t('statusModal.noSkills') || '尚未習得任何技能'}</div>`;
    } else {
      skillsHtml = `
        <div class="status-skills-grid">
          ${acquired
            .map(({ card, level }) => {
              const title = i18n.t(`talents.${card.id}.title`) || card.title;
              const badge = i18n.t(`talents.${card.id}.badge`) || card.badge;
              const desc = card.getDescription(level - 1);
              const pct = Math.min(100, Math.round((level / card.maxLevel) * 100));
              const isMax = level >= card.maxLevel;

              return `
              <div class="status-skill-card ${isMax ? 'skill-max' : ''}">
                <div class="skill-card-top">
                  <div class="skill-icon-wrap">
                    ${getSurvivorSvg(card.iconKey, 24, isMax ? '#ffd700' : '#00e676')}
                  </div>
                  <div class="skill-main-info">
                    <div class="skill-title-row">
                      <span class="skill-title">${title}</span>
                      <span class="skill-level-tag ${isMax ? 'max-tag' : ''}">
                        ${isMax ? (i18n.t('statusModal.maxLevelReached') || 'MAX') : `Lv ${level} / ${card.maxLevel}`}
                      </span>
                    </div>
                    <span class="skill-badge">${badge}</span>
                  </div>
                </div>
                <div class="skill-progress-bar">
                  <div class="skill-progress-fill" style="width: ${pct}%;"></div>
                </div>
                <div class="skill-desc-text">${desc}</div>
              </div>
            `;
            })
            .join('')}
        </div>
      `;
    }

    this.element.innerHTML = `
      <div class="game-modal status-modal-card">
        <header class="status-modal-header">
          <div class="status-header-info">
            <h2 class="status-modal-title">${i18n.t('statusModal.title') || '角色狀態'}</h2>
            <div class="status-pills">
              <span class="status-pill stage-pill">${i18n.t('hud.stage') || '關卡'} ${engine.stage ?? 1}</span>
              <span class="status-pill level-pill">${i18n.t('hud.level') || '等級'} ${engine.level ?? 1}</span>
            </div>
          </div>
          <button id="btn-status-close-x" class="status-close-icon" title="${i18n.t('statusModal.resume') || '關閉'}" aria-label="Close">
            ✕
          </button>
        </header>

        <div class="status-modal-body">
          <section class="status-section">
            <h3 class="status-section-title">${i18n.t('statusModal.combatStats') || '即時戰鬥素質'}</h3>
            <div class="status-stats-grid">
              <div class="status-stat-box">
                <span class="stat-name">${i18n.t('statusModal.hp') || '生命值'}</span>
                <span class="stat-num hp-val">${hp} / ${maxHp}</span>
              </div>
              <div class="status-stat-box">
                <span class="stat-name">${i18n.t('statusModal.damage') || '攻擊增幅'}</span>
                <span class="stat-num dmg-val">${damageText}</span>
              </div>
              <div class="status-stat-box">
                <span class="stat-name">${i18n.t('statusModal.speed') || '移動速度'}</span>
                <span class="stat-num spd-val">${speedVal} / 4.4</span>
              </div>
              <div class="status-stat-box">
                <span class="stat-name">${i18n.t('statusModal.defense') || '傷害減免'}</span>
                <span class="stat-num def-val">${defensePct}%</span>
              </div>
              <div class="status-stat-box">
                <span class="stat-name">${i18n.t('statusModal.magnet') || '磁吸半徑'}</span>
                <span class="stat-num mag-val">${magnetRad}</span>
              </div>
              <div class="status-stat-box">
                <span class="stat-name">${i18n.t('statusModal.critRate') || '暴擊機率'}</span>
                <span class="stat-num crit-val">${critPct}</span>
              </div>
              <div class="status-stat-box">
                <span class="stat-name">${i18n.t('statusModal.hpRegen') || '生命秒回'}</span>
                <span class="stat-num regen-val">${hpRegen}</span>
              </div>
              <div class="status-stat-box">
                <span class="stat-name">${i18n.t('statusModal.kills') || '累積擊殺'}</span>
                <span class="stat-num kill-val">${kills}</span>
              </div>
              <div class="status-stat-box">
                <span class="stat-name">${i18n.t('statusModal.surviveTime') || '存活時間'}</span>
                <span class="stat-num time-val">${timeFormatted}</span>
              </div>
            </div>
          </section>

          <section class="status-section">
            <h3 class="status-section-title">${i18n.t('statusModal.skillsTitle') || '已習得技能卡'} (${acquired.length})</h3>
            ${skillsHtml}
          </section>
        </div>

        <footer class="status-modal-footer">
          <button id="btn-status-resume-btn" class="modal-primary-btn status-resume-btn">
            ${i18n.t('statusModal.resume') || '繼續戰鬥'}
          </button>
        </footer>
      </div>
    `;

    const resumeAction = () => {
      this.hide();
      this.options.onResume();
    };

    const btnResume = this.element.querySelector('#btn-status-resume-btn');
    if (btnResume) {
      btnResume.addEventListener('click', resumeAction);
      btnResume.addEventListener('touchend', (e) => {
        e.preventDefault();
        resumeAction();
      });
    }

    const btnCloseX = this.element.querySelector('#btn-status-close-x');
    if (btnCloseX) {
      btnCloseX.addEventListener('click', resumeAction);
      btnCloseX.addEventListener('touchend', (e) => {
        e.preventDefault();
        resumeAction();
      });
    }
  }
}
