import { ArtisanForgeService } from '../services/ArtisanForgeService.ts';
import { SnekInventoryService } from '../services/SnekInventoryService.ts';
import { SnekPassportStorage } from '../storage/SnekPassportStorage.ts';
import {
  ExpeditionReceipt,
  ExpeditionSettlementResult,
  ISnekWorldPlugin,
  SnekPetPassport,
  SnekWorldContext,
} from '../types.ts';

export const MAX_GOLD_PER_EXPEDITION = 5000;
export const MAX_EXP_PER_EXPEDITION = 2500;
export const DEFEAT_GOLD_RETENTION_RATIO = 0.6; // 戰敗送回家園保留當趟 60% 金幣，既有家園存款與武器 100% 不掉

function deepFreezeClone<T>(obj: T): Readonly<T> {
  const clone = JSON.parse(JSON.stringify(obj));
  const freezeRecursive = (target: any) => {
    if (target && typeof target === 'object') {
      Object.freeze(target);
      Object.keys(target).forEach((key) => freezeRecursive(target[key]));
    }
  };
  freezeRecursive(clone);
  return clone;
}

export interface SnekPortalHostOptions {
  storage?: SnekPassportStorage;
  onReturnToHub?: (result: ExpeditionSettlementResult) => void;
}

export class SnekPortalHost {
  private storage: SnekPassportStorage;
  private plugins: Map<string, ISnekWorldPlugin> = new Map();
  private activeCleanup: (() => void) | null = null;
  private activeWorldId: string | null = null;
  private onReturnToHub?: (result: ExpeditionSettlementResult) => void;

  constructor(options: SnekPortalHostOptions = {}) {
    this.storage = options.storage || new SnekPassportStorage();
    this.onReturnToHub = options.onReturnToHub;
  }

  public getStorage(): SnekPassportStorage {
    return this.storage;
  }

  public registerWorld(plugin: ISnekWorldPlugin): void {
    this.plugins.set(plugin.worldId, plugin);
  }

  public getRegisteredWorlds(): ISnekWorldPlugin[] {
    return Array.from(this.plugins.values());
  }

  public getActiveWorldId(): string | null {
    return this.activeWorldId;
  }

  /**
   * 傳送出發 (Jack-In)：將 Snek 寵物護照以唯讀快照方式傳入目標同專案玩法世界
   */
  public jackIn(worldId: string, container: HTMLElement): () => void {
    const plugin = this.plugins.get(worldId);
    if (!plugin) {
      throw new Error(`World plugin not registered: ${worldId}`);
    }

    if (this.activeCleanup) {
      this.activeCleanup();
      this.activeCleanup = null;
    }

    this.activeWorldId = worldId;

    const context: SnekWorldContext = {
      worldId,
      getPassport: () => deepFreezeClone(this.storage.load()),
      getCombatProfile: () => ArtisanForgeService.resolveCombatStats(this.storage.load()),
      jackOut: (partialReceipt) => {
        const fullReceipt: ExpeditionReceipt = {
          ...partialReceipt,
          worldId,
        };
        return this.jackOut(fullReceipt);
      },
    };

    const cleanup = plugin.mount(container, context);
    this.activeCleanup = () => {
      cleanup();
      this.activeWorldId = null;
    };

    return this.activeCleanup;
  }

  /**
   * 冒險回歸 (Jack-Out)：驗證外部/插件世界回傳的結算單並安全寫回 localStorage
   */
  public jackOut(receipt: ExpeditionReceipt): ExpeditionSettlementResult {
    if (this.activeCleanup) {
      this.activeCleanup();
      this.activeCleanup = null;
    }

    const result = this.settleExpedition(receipt);
    this.onReturnToHub?.(result);
    return result;
  }

  /**
   * 驗證並結算冒險收穫（可獨立呼叫供單元測試與引擎同步）
   */
  public settleExpedition(receipt: ExpeditionReceipt): ExpeditionSettlementResult {
    const current = this.storage.load();

    // 1. 防作弊上限與非負數夾制
    const rawGold = Math.max(0, Math.min(MAX_GOLD_PER_EXPEDITION, Math.floor(receipt.goldEarned || 0)));
    const rawExp = Math.max(0, Math.min(MAX_EXP_PER_EXPEDITION, Math.floor(receipt.expEarned || 0)));
    const stageReached = Math.max(1, Math.floor(receipt.stageReached || 1));

    // 2. 撤離 vs 戰敗折損規則
    const finalGoldAdded =
      receipt.outcome === 'EXTRACTED'
        ? rawGold
        : Math.floor(rawGold * DEFEAT_GOLD_RETENTION_RATIO);
    const finalExpAdded = rawExp;

    // 3. 等級與經驗值提升計算
    let level = current.level;
    let exp = current.exp + finalExpAdded;
    let leveledUp = false;

    while (exp >= level * 100) {
      exp -= level * 100;
      level += 1;
      leveledUp = true;
    }

    // 4. 素材與戰利品入庫（嚴格受隨身背包容量上限 backpackCapacity 限制）
    let nextInventory = { ...current.inventory };
    if (receipt.itemsFound) {
      const sanitizedItems: Record<string, number> = {};
      for (const [itemId, count] of Object.entries(receipt.itemsFound)) {
        const safeCount = Math.max(0, Math.min(99, Math.floor(count || 0)));
        if (safeCount > 0) {
          sanitizedItems[itemId] = safeCount;
        }
      }
      const bagResult = SnekInventoryService.addItemsToBackpack(current, sanitizedItems);
      nextInventory = bagResult.passport.inventory;
    }

    // 5. 世界最高進度紀錄
    const prevWorld = current.worldProgress[receipt.worldId] || {
      highestStage: 1,
      clears: 0,
    };
    const nextWorldProgress = {
      ...current.worldProgress,
      [receipt.worldId]: {
        highestStage: Math.max(prevWorld.highestStage, stageReached),
        clears: prevWorld.clears + (receipt.outcome === 'EXTRACTED' ? 1 : 0),
      },
    };

    // 6. 若在副本中獲得更高階武器突破，保留強化等級與附魔並升階
    let nextPassport: SnekPetPassport = {
      ...current,
      level,
      exp,
      moodEmote: receipt.outcome === 'EXTRACTED' ? 'happy' : 'sleep',
      wallet: {
        gold: current.wallet.gold + finalGoldAdded,
      },
      inventory: nextInventory,
      worldProgress: nextWorldProgress,
    };

    if (
      typeof receipt.upgradedWeaponTier === 'number' &&
      receipt.upgradedWeaponTier > nextPassport.equippedWeapon.tier
    ) {
      nextPassport = ArtisanForgeService.evolveWeaponTier(
        nextPassport,
        receipt.upgradedWeaponTier - 1
      );
    }

    const saved = this.storage.save(nextPassport);

    return {
      accepted: true,
      finalGoldAdded,
      finalExpAdded,
      leveledUp,
      newLevel: level,
      updatedPassport: deepFreezeClone(saved),
    };
  }
}
