export interface SnekPetHomeViewOptions {
  storage?: SnekPassportStorage;
  onLaunchGame?: (worldId: string) => void;
}

/**
 * 依據螢幕解析度動態計算相機視錐 (Camera Frustum Fitting)
 * 確保小蛇本體與念力銃槍總寬度在直向手機上佔比不超過螢幕 60%，防超出畫面
 */
export function calculateCameraFitting(width: number, height: number): {
  fov: number;
  position: [number, number, number];
  lookAt: [number, number, number];
} {
  const aspect = Math.max(0.1, width / (height || 1));
  const fov = 40;
  const fovRad = (fov * Math.PI) / 180;

  // 小蛇本體加上浮空念力銃槍總邊界約寬 2.6、高 2.0
  const heroBoundingWidth = 2.6;
  const heroBoundingHeight = 2.0;

  // 直向手機限制小蛇佔螢幕寬度約 58% 以下，高度佔 42% 以下，留出安全視野
  const desiredWidth = heroBoundingWidth / 0.58;
  const desiredHeight = heroBoundingHeight / 0.42;

  const distForHeight = (desiredHeight / 2) / Math.tan(fovRad / 2);
  const distForWidth = (desiredWidth / 2) / (Math.tan(fovRad / 2) * aspect);
  const targetDist = Math.max(distForHeight, distForWidth);

  return {
    fov,
    position: [0, 1.25, Math.min(15, Math.max(5.5, targetDist))],
    lookAt: [0, 0.95, 0],
  };
}

