import { IBalanceRule } from '../IBalanceRule.ts';
import { PacingMetrics, PacingModifiers, PacingState } from '../types.ts';

/**
 * BossConvergenceRule (首領決戰收斂規則)
 * When a boss fight drags beyond 45 seconds and boss HP remains substantial (>40%),
 * smoothly increases boss damage vulnerability to converge the fight within 1.5 to 2 minutes.
 */
export class BossConvergenceRule implements IBalanceRule {
  public readonly id = 'BOSS_CONVERGENCE_RULE';

  public evaluate(
    metrics: PacingMetrics,
    modifiers: PacingModifiers,
    currentState: PacingState
  ): PacingState | void {
    if (metrics.bossCombatTime > 45 && metrics.bossHpRatio > 0.35) {
      // Scales from 1.25x at 45s up to 1.50x at 75s+
      const progress = Math.min(1.0, (metrics.bossCombatTime - 45) / 30);
      const vuln = 1.25 + progress * 0.25;
      modifiers.bossDamageTakenMultiplier = Math.max(modifiers.bossDamageTakenMultiplier, vuln);
      return 'BOSS_CONVERGENCE';
    }
    return currentState;
  }
}
