import { IBalanceRule } from './IBalanceRule.ts';
import {
  createDefaultPacingModifiers,
  PacingMetrics,
  PacingModifiers,
  PacingState,
} from './types.ts';
import { SlogAssistRule } from './rules/SlogAssistRule.ts';
import { BossConvergenceRule } from './rules/BossConvergenceRule.ts';
import { PinchRescueRule } from './rules/PinchRescueRule.ts';
import { BossTacticalPacingRule } from './rules/BossTacticalPacingRule.ts';
import { FiveLevelMilestoneRule } from './rules/FiveLevelMilestoneRule.ts';

/**
 * DynamicBalanceDirector (動態平衡導演系統)
 * Pure OOP Coordinator / Strategy Orchestrator.
 * Dynamically evaluates registered balancing rules every frame, updates pacing state,
 * and yields active multipliers to keep game flow within the target clear time.
 */
export class DynamicBalanceDirector {
  private state: PacingState = 'FLOW';
  private rules: IBalanceRule[] = [];
  private modifiers: PacingModifiers = createDefaultPacingModifiers();
  private timeSinceLevelUp: number = 0;
  private bossCombatTime: number = 0;

  constructor() {
    this.registerRule(new FiveLevelMilestoneRule());
    this.registerRule(new BossTacticalPacingRule());
    this.registerRule(new SlogAssistRule());
    this.registerRule(new BossConvergenceRule());
    this.registerRule(new PinchRescueRule());
  }

  public registerRule(rule: IBalanceRule): void {
    this.rules.push(rule);
  }

  public getState(): PacingState {
    return this.state;
  }

  public getModifiers(): PacingModifiers {
    return { ...this.modifiers };
  }

  public notifyLevelUp(): void {
    this.timeSinceLevelUp = 0;
    this.state = 'FLOW';
    this.modifiers = createDefaultPacingModifiers();
  }

  public notifyBossSpawn(): void {
    this.bossCombatTime = 0;
  }

  public notifyBossDefeat(): void {
    this.bossCombatTime = 0;
    this.state = 'FLOW';
    this.modifiers = createDefaultPacingModifiers();
  }

  public update(dtSec: number, metrics?: Partial<PacingMetrics>): void {
    this.timeSinceLevelUp = metrics?.timeSinceLevelUp ?? (this.timeSinceLevelUp + dtSec);
    if (metrics?.bossCombatTime !== undefined) {
      this.bossCombatTime = metrics.bossCombatTime;
    } else if (metrics?.bossHpRatio && metrics.bossHpRatio > 0) {
      this.bossCombatTime += dtSec;
    } else {
      this.bossCombatTime = 0;
    }

    const fullMetrics: PacingMetrics = {
      timeSinceLevelUp: this.timeSinceLevelUp,
      bossCombatTime: this.bossCombatTime,
      bossHpRatio: metrics?.bossHpRatio ?? 0,
      playerHpRatio: metrics?.playerHpRatio ?? 1.0,
      stage: metrics?.stage ?? 1,
      level: metrics?.level ?? 1,
    };

    const newMods = createDefaultPacingModifiers();
    let nextState: PacingState = 'FLOW';

    for (const rule of this.rules) {
      const resultingState = rule.evaluate(fullMetrics, newMods, nextState);
      if (resultingState && resultingState !== 'FLOW') {
        nextState = resultingState;
      }
    }

    this.state = nextState;
    this.modifiers = newMods;
  }

  public reset(): void {
    this.state = 'FLOW';
    this.modifiers = createDefaultPacingModifiers();
    this.timeSinceLevelUp = 0;
    this.bossCombatTime = 0;
  }
}
