import { ISkillCard, SkillCardContext } from '../ISkillCard.ts';

export class CooldownQuantCard implements ISkillCard {
  public readonly id = 'COOLDOWN_QUANT';
  public readonly title = '高頻量化降頻';
  public readonly badge = '算法撮合';
  public readonly category = 'STATS';
  public readonly iconKey = 'lightning';
  public readonly maxLevel = 8;
  public readonly financeTerm = '【高頻量化 (HFT)】利用高速電腦演算法以微秒級速度執行交易指令。';

  public getDescription(currentLevel: number): string {
    const next = currentLevel + 1;
    return `全局武器攻擊冷卻縮短 ${(next * 4)}%，大幅提高發射與旋轉頻率`;
  }

  public isEligible(context: SkillCardContext): boolean {
    const current = context.engine.skillLevels?.get(this.id) ?? 0;
    return current < this.maxLevel;
  }

  public apply(context: SkillCardContext, nextLevel: number): void {
    context.engine.cooldownReduction = Math.min(0.32, nextLevel * 0.04);
  }
}
