import { IBalanceRule } from '../IBalanceRule.ts';
import { PacingMetrics, PacingModifiers, PacingState } from '../types.ts';

/**
 * BossTacticalPacingRule (首領戰術防秒殺守門員規則)
 * Prevents overpowered player builds from instantly melting bosses in 1-2 seconds.
 * During the initial tactical engagement window (first 10-12s), if boss HP is plummeting
 * faster than tactical safety thresholds, activates Market Defense / Tactical Hardening,
 * ensuring bosses survive at least 12 seconds to showcase their combat patterns and tension.
 */
export class BossTacticalPacingRule implements IBalanceRule {
  public readonly id = 'BOSS_TACTICAL_PACING_RULE';

  public evaluate(
    metrics: PacingMetrics,
    modifiers: PacingModifiers,
    currentState: PacingState
  ): PacingState | void {
    if (metrics.bossCombatTime <= 0 || metrics.bossHpRatio <= 0) {
      return currentState;
    }

    // Opening Tactical Phase: enforce minimum tactical combat duration by stage
    const minTacticalWindow = metrics.stage >= 10 ? 35 : metrics.stage >= 5 ? 14 : 12;
    if (metrics.bossCombatTime < minTacticalWindow) {
      // In opening window, boss health should not drop faster than smooth tactical pacing curve
      const minExpectedRatio = Math.max(0.12, 1.0 - (metrics.bossCombatTime / minTacticalWindow) * 0.88);
      if (metrics.bossHpRatio < minExpectedRatio) {
        // Extreme DPS burst: suppress incoming spike damage dynamically
        const suppression = Math.max(0.06, (metrics.bossHpRatio / minExpectedRatio) * 0.35);
        modifiers.bossDamageTakenMultiplier = Math.min(modifiers.bossDamageTakenMultiplier, suppression);
        return 'BOSS_TACTICAL_DEFENSE';
      }
    }

    return currentState;
  }
}
