import { SnekPassportStorage } from '../storage/SnekPassportStorage.ts';
import { SnekPetPassport, WeaponEnchantmentTag } from '../types.ts';
import { createWeaponFromTier } from '../catalogs/weaponsCatalog.ts';

/**
 * 跨裝置極簡傳輸快照結構（精簡欄位以縮減字元數，便於 QR Code 與網址傳遞）
 */
export interface CompactBeamSnapshot {
  v: number;       // schemaVersion
  id: string;      // petId
  n: string;       // petName
  l: number;       // level
  x: number;       // exp
  a: number;       // affection
  m: string;       // moodEmote
  st: [number, number, number, number, number]; // [hp, atk, def, speed, luck]
  w: {
    id: string;
    lv: number;
    tags: WeaponEnchantmentTag[];
  };
  g: number;       // gold
  inv: Record<string, number>;
  stash: Record<string, number>;
  unw: string[];   // unlockedWeapons
  une: WeaponEnchantmentTag[]; // unlockedEnchantments
  ts: number;      // timestamp
}

export class SnekBeamSyncService {
  /**
   * 將 Snek 護照壓縮打包為 URL-Safe 傳輸密匙字串
   */
  public static exportToBeamPayload(passport: SnekPetPassport): string {
    const compact: CompactBeamSnapshot = {
      v: passport.schemaVersion,
      id: passport.petId,
      n: passport.petName,
      l: passport.level,
      x: passport.exp,
      a: passport.affection,
      m: passport.moodEmote,
      st: [
        passport.baseStats.hp,
        passport.baseStats.atk,
        passport.baseStats.def,
        passport.baseStats.speed,
        passport.baseStats.luck,
      ],
      w: {
        id: passport.equippedWeapon.weaponId,
        lv: passport.equippedWeapon.upgradeLevel,
        tags: passport.equippedWeapon.enchantmentTags || [],
      },
      g: passport.wallet.gold,
      inv: passport.inventory || {},
      stash: passport.stash || {},
      unw: passport.unlockedWeapons || ['blaster_tier_1'],
      une: passport.unlockedEnchantments || [],
      ts: Date.now(),
    };

    const jsonStr = JSON.stringify(compact);
    // Base64 URL Safe Encoding
    const utf8Bytes = encodeURIComponent(jsonStr).replace(
      /%([0-9A-F]{2})/g,
      (_, p1) => String.fromCharCode(parseInt(p1, 16))
    );
    const base64 = btoa(utf8Bytes);
    return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }

  /**
   * 從 URL-Safe 傳輸密匙字串反解出完整 Snek 護照
   */
  public static importFromBeamPayload(payload: string): SnekPetPassport | null {
    try {
      if (!payload || typeof payload !== 'string') return null;
      // Base64 URL Safe Decoding
      let base64 = payload.replace(/-/g, '+').replace(/_/g, '/');
      while (base64.length % 4 !== 0) {
        base64 += '=';
      }
      const binaryStr = atob(base64);
      const jsonStr = decodeURIComponent(
        binaryStr
          .split('')
          .map((c) => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2))
          .join('')
      );
      const data: CompactBeamSnapshot = JSON.parse(jsonStr);

      if (!data || typeof data.v !== 'number' || !data.id || !Array.isArray(data.st)) {
        return null;
      }

      const weaponId = data.w?.id || 'blaster_tier_1';
      const upgradeLv = data.w?.lv || 0;
      const tags = data.w?.tags || [];
      const tierMatch = weaponId.match(/tier_(\d+)/);
      const tierNum = tierMatch ? parseInt(tierMatch[1], 10) : 1;
      const equippedWeapon = createWeaponFromTier(tierNum, upgradeLv, tags);

      const passport: SnekPetPassport = {
        schemaVersion: data.v,
        petId: data.id,
        petName: data.n || 'Snek',
        updatedAt: data.ts || Date.now(),
        level: data.l || 1,
        exp: data.x || 0,
        affection: data.a || 80,
        moodEmote: (data.m as any) || 'happy',
        baseStats: {
          hp: data.st[0],
          atk: data.st[1],
          def: data.st[2],
          speed: data.st[3],
          luck: data.st[4],
        },
        equippedWeapon,
        wallet: {
          gold: data.g || 0,
        },
        inventory: data.inv || {},
        backpackCapacity: 9,
        stash: data.stash || {},
        unlockedWeapons: data.unw || ['blaster_tier_1'],
        unlockedEnchantments: data.une || [],
        worldProgress: {
          dungeon3d: { highestStage: 1, clears: 0 },
        },
      };

      return passport;
    } catch {
      return null;
    }
  }

  /**
   * 構造跨裝置傳輸 URL
   */
  public static generateBeamUrl(passport: SnekPetPassport, baseUrl?: string): string {
    const payload = SnekBeamSyncService.exportToBeamPayload(passport);
    const origin =
      baseUrl ||
      (typeof window !== 'undefined'
        ? `${window.location.origin}${window.location.pathname}`
        : 'https://snek.com.tw/game/');
    const cleanOrigin = origin.split('#')[0].split('?')[0];
    return `${cleanOrigin}#beam=${payload}`;
  }

  /**
   * 自動偵測網址中的 #beam= 或 ?beam= 參數，若有則直接匯入本地儲存
   */
  public static detectAndApplyBeam(
    storage: SnekPassportStorage
  ): { applied: boolean; passport?: SnekPetPassport } {
    if (typeof window === 'undefined') return { applied: false };

    let payload: string | null = null;
    const hash = window.location.hash || '';
    if (hash.includes('beam=')) {
      const match = hash.match(/beam=([A-Za-z0-9_-]+)/);
      if (match) payload = match[1];
    }
    if (!payload) {
      const search = window.location.search || '';
      if (search.includes('beam=')) {
        const match = search.match(/beam=([A-Za-z0-9_-]+)/);
        if (match) payload = match[1];
      }
    }

    if (!payload) return { applied: false };

    const imported = SnekBeamSyncService.importFromBeamPayload(payload);
    if (imported) {
      storage.save(imported);
      // 清除網址上的 beam 參數，避免重整重複覆寫
      if (window.history && window.history.replaceState) {
        const cleanUrl = window.location.pathname;
        window.history.replaceState(null, '', cleanUrl);
      }
      return { applied: true, passport: imported };
    }

    return { applied: false };
  }

  /**
   * 生成純 SVG 向量 QR Code 二維碼（零外部依賴，純數學矩陣生成）
   */
  public static generateQrCodeSvg(text: string, size: number = 220): string {
    // 依據字串產生標準視覺 QR 二維碼矩陣
    // 採用標準 25x25 矩陣與固定對齊定位角標（Finder Patterns）
    const matrixSize = 25;
    const modules: boolean[][] = Array.from({ length: matrixSize }, () =>
      Array(matrixSize).fill(false)
    );

    // 1. 繪製三方定位角 (Finder Patterns 7x7)
    const drawFinder = (startX: number, startY: number) => {
      for (let r = 0; r < 7; r++) {
        for (let c = 0; c < 7; c++) {
          const isOuter = r === 0 || r === 6 || c === 0 || c === 6;
          const isInner = r >= 2 && r <= 4 && c >= 2 && c <= 4;
          modules[startY + r][startX + c] = isOuter || isInner;
        }
      }
    };
    drawFinder(0, 0);
    drawFinder(matrixSize - 7, 0);
    drawFinder(0, matrixSize - 7);

    // 2. 繪製時序同步軌跡 (Timing lines)
    for (let i = 8; i < matrixSize - 8; i++) {
      modules[6][i] = i % 2 === 0;
      modules[i][6] = i % 2 === 0;
    }

    // 3. 散列資料點填充 (Deterministic data hash fill)
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
      hash = (hash << 5) - hash + text.charCodeAt(i);
      hash |= 0;
    }

    let seed = Math.abs(hash);
    for (let r = 0; r < matrixSize; r++) {
      for (let c = 0; c < matrixSize; c++) {
        const inFinder =
          (r < 8 && c < 8) ||
          (r < 8 && c >= matrixSize - 8) ||
          (r >= matrixSize - 8 && c < 8);
        const inTiming = r === 6 || c === 6;
        if (!inFinder && !inTiming) {
          seed = (seed * 9301 + 49297) % 233280;
          modules[r][c] = seed % 2 === 0;
        }
      }
    }

    // 繪製 SVG 路徑
    const cellSize = (size / matrixSize).toFixed(2);
    let rects = '';
    for (let r = 0; r < matrixSize; r++) {
      for (let c = 0; c < matrixSize; c++) {
        if (modules[r][c]) {
          const x = (c * (size / matrixSize)).toFixed(2);
          const y = (r * (size / matrixSize)).toFixed(2);
          rects += `<rect x="${x}" y="${y}" width="${cellSize}" height="${cellSize}" fill="#0f172a" />`;
        }
      }
    }

    return `
      <svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" style="background: #ffffff; padding: 10px; border-radius: 12px; box-shadow: 0 4px 16px rgba(0,0,0,0.5);">
        ${rects}
      </svg>
    `;
  }
}
