/**
 * SnekPetSDK 行動端效能、節能與生命週期治理器 (參考規格書 08 & 09)
 * 提供：
 * 1. DevicePixelRatio (DPR) 2.0x 硬上限計算
 * 2. 120Hz/144Hz 螢幕之 60 FPS 自適應幀率節流器 (15.6ms 門檻)
 * 3. document.hidden 背景分頁與鎖屏自動休眠 + 前台喚醒時間差校準
 * 4. 暫停狀態 (isPaused) 首幀靜態保留與後續重複渲染略過
 */
export interface MobileGovernorOptions {
  onUpdate: (deltaSec: number) => void;
  onRender: (deltaSec: number) => void;
  onAudioUnlockGesture?: () => void;
  targetFps?: number;
}

export const MAX_MOBILE_DPR = 2.0;
export const DEFAULT_FRAME_BUDGET_MS = 15.6; // 60 FPS (16.67ms) with 1.07ms jitter tolerance

export class MobileLifecycleGovernor {
  public isRunning: boolean = false;
  public isSleeping: boolean = false;
  public isPaused: boolean = false;

  private onUpdate: (deltaSec: number) => void;
  private onRender: (deltaSec: number) => void;
  private onAudioUnlockGesture?: () => void;
  private frameBudgetMs: number;

  private animFrameId: number | null = null;
  private lastTime: number = 0;
  private hasRenderedPausedFrame: boolean = false;

  private visibilityHandler: () => void;
  private gestureHandler: () => void;

  constructor(options: MobileGovernorOptions) {
    this.onUpdate = options.onUpdate;
    this.onRender = options.onRender;
    this.onAudioUnlockGesture = options.onAudioUnlockGesture;
    this.frameBudgetMs = options.targetFps
      ? 1000 / options.targetFps - 1.0
      : DEFAULT_FRAME_BUDGET_MS;

    this.visibilityHandler = () => this.handleVisibilityChange();
    this.gestureHandler = () => {
      this.onAudioUnlockGesture?.();
    };
  }

  /**
   * 規格書 09 (2.2)：將 DevicePixelRatio 嚴格封頂在 2.0x，減少旗艦手機 55% 像素填充負載
   */
  public static getClampedDpr(rawDpr: number = window.devicePixelRatio || 1): number {
    return Math.min(Math.max(1.0, rawDpr), MAX_MOBILE_DPR);
  }

  public start(): void {
    if (this.isRunning) return;
    this.isRunning = true;
    this.isSleeping = false;
    this.lastTime = performance.now();

    document.addEventListener('visibilitychange', this.visibilityHandler);
    window.addEventListener('pointerdown', this.gestureHandler, { passive: true });
    window.addEventListener('touchstart', this.gestureHandler, { passive: true });

    this.scheduleNextFrame();
  }

  public stop(): void {
    this.isRunning = false;
    this.cancelScheduledFrame();
    document.removeEventListener('visibilitychange', this.visibilityHandler);
    window.removeEventListener('pointerdown', this.gestureHandler);
    window.removeEventListener('touchstart', this.gestureHandler);
  }

  public pause(): void {
    if (this.isPaused) return;
    this.isPaused = true;
    this.hasRenderedPausedFrame = false;
  }

  public resume(): void {
    if (!this.isPaused) return;
    this.isPaused = false;
    this.hasRenderedPausedFrame = false;
    this.lastTime = performance.now();
  }

  /**
   * 單步執行循環（公開供整合測試直接傳入 timestamp 驗證 120Hz 節流與暫停跳幀）
   */
  public stepFrame(currentTime: number): boolean {
    if (!this.isRunning || this.isSleeping) return false;

    const deltaMs = currentTime - this.lastTime;
    // 規格書 09 (2.1)：小於 15.6ms 直接放行，抑制 120Hz/144Hz 螢幕雙倍耗電
    if (deltaMs < this.frameBudgetMs) {
      return false;
    }

    this.lastTime = currentTime;
    const deltaSec = Math.min(Math.max(0.001, deltaMs / 1000), 0.1);

    // 規格書 09 (2.4)：暫停時僅繪製首個靜態幀，後續略過重繪
    if (this.isPaused) {
      if (!this.hasRenderedPausedFrame) {
        this.hasRenderedPausedFrame = true;
        this.onRender(0);
        return true;
      }
      return false;
    }

    this.onUpdate(deltaSec);
    this.onRender(deltaSec);
    return true;
  }

  private scheduleNextFrame(): void {
    if (!this.isRunning || this.isSleeping) return;
    this.animFrameId = requestAnimationFrame((now) => {
      this.stepFrame(now);
      if (this.isRunning && !this.isSleeping) {
        this.scheduleNextFrame();
      }
    });
  }

  private cancelScheduledFrame(): void {
    if (this.animFrameId !== null) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
  }

  private handleVisibilityChange(): void {
    if (document.hidden) {
      // 規格書 09 (2.3)：背景分頁與鎖屏立即休眠並取消 RAF
      this.isSleeping = true;
      this.cancelScheduledFrame();
    } else {
      // 回到前景時平滑喚醒並重設 lastTime 避免巨大 deltaSec 暴衝
      this.isSleeping = false;
      this.lastTime = performance.now();
      this.onAudioUnlockGesture?.();
      this.scheduleNextFrame();
    }
  }
}
