import { ISkillCard, SkillCardContext } from '../ISkillCard.ts';

export class MarketMakerLuckCard implements ISkillCard {
  public readonly id = 'MARKET_MAKER_LUCK';
  public readonly title = '做市商流動性深度';
  public readonly badge = '幸運造市';
  public readonly category = 'SPECIAL';
  public readonly iconKey = 'banknote';
  public readonly maxLevel = 8;
  public readonly financeTerm = '【做市商 (Market Maker)】提供連續雙邊報價以創造市場交易流動性的流動性提供者。';

  public getDescription(currentLevel: number): string {
    const next = currentLevel + 1;
    return `怪物擊殺時有 ${(next * 5)}% 機率額外掉落雙倍經驗水晶與戰場補給道具`;
  }

  public isEligible(context: SkillCardContext): boolean {
    const current = context.engine.skillLevels?.get(this.id) ?? 0;
    return current < this.maxLevel;
  }

  public apply(context: SkillCardContext, nextLevel: number): void {
    context.engine.lootBonus = nextLevel * 0.05;
  }
}
