import * as THREE from 'three';
import { EMOTE_ICON_MAP } from '../catalogs/weaponsCatalog.ts';
import { SnekEmoteType } from '../types.ts';

export class SnekEmoteBubble3D {
  public mesh: THREE.Mesh;
  public currentEmote: SnekEmoteType | null = null;
  private timer: number = 0;
  private maxDuration: number = 1.5;
  private materials: Partial<Record<SnekEmoteType, THREE.MeshBasicMaterial>> = {};
  private texLoader: THREE.TextureLoader;

  constructor(parentGroup: THREE.Group) {
    this.texLoader = new THREE.TextureLoader();

    const geo = new THREE.PlaneGeometry(0.68, 0.68);
    const defaultMat = new THREE.MeshBasicMaterial({
      transparent: true,
      opacity: 0,
      depthWrite: false,
      side: THREE.DoubleSide,
    });

    this.mesh = new THREE.Mesh(geo, defaultMat);
    // Positioned at upper-left of Snek's head (complementing the telekinetic weapon at upper-right)
    this.mesh.position.set(-0.72, 2.32, 0.22);
    this.mesh.rotation.x = -0.32;
    this.mesh.visible = false;
    parentGroup.add(this.mesh);
  }

  private getOrLoadMaterial(emote: SnekEmoteType): THREE.MeshBasicMaterial {
    if (this.materials[emote]) {
      return this.materials[emote]!;
    }
    const url = EMOTE_ICON_MAP[emote] || EMOTE_ICON_MAP.happy;
    const mat = new THREE.MeshBasicMaterial({
      transparent: true,
      opacity: 1,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    const tex = this.texLoader.load(url, (t) => {
      t.colorSpace = THREE.SRGBColorSpace;
      mat.needsUpdate = true;
    });
    mat.map = tex;
    this.materials[emote] = mat;
    return mat;
  }

  public showEmote(emote: SnekEmoteType, duration: number = 1.6): void {
    this.currentEmote = emote;
    this.maxDuration = Math.max(0.2, duration);
    this.timer = this.maxDuration;
    this.mesh.material = this.getOrLoadMaterial(emote);
    this.mesh.visible = true;
    this.mesh.scale.setScalar(0.2);
  }

  public update(delta: number): void {
    if (this.timer <= 0 || !this.mesh.visible) return;

    this.timer -= delta;
    if (this.timer <= 0) {
      this.mesh.visible = false;
      this.currentEmote = null;
      return;
    }

    const elapsed = this.maxDuration - this.timer;
    // Pop-in bounce during first 0.2s, gentle float in middle, fade out at end
    const popScale = elapsed < 0.2 ? 0.2 + (elapsed / 0.2) * 0.95 : 1.0 + Math.sin(elapsed * 6) * 0.06;
    this.mesh.scale.setScalar(popScale);
    this.mesh.position.y = 2.32 + Math.sin(elapsed * 4) * 0.08;
  }
}
