    this.placeGLB(`${surv}/workbench-anvil.glb`, 5.3, 0, 1.8, 1.75, -Math.PI / 2);
    this.placeGLB(`${surv}/workbench-grind.glb`, 5.3, 0, 3.3, 1.55, -Math.PI / 2);
    this.placeGLB(`${surv}/resource-stone-large.glb`, 3.2, 0, 0.8, 1.15, 0.4);
