import { IBalanceRule } from '../IBalanceRule.ts';
import { PacingMetrics, PacingModifiers, PacingState } from '../types.ts';

/**
 * FiveLevelMilestoneRule (每五等里程碑雙向動態平衡系統)
 * 以每 5 等（Lv. 5, 10, 15... 100）為動態節點，進行真正的雙向平衡：
 * - 絕不一昧輔助角色變強：當玩家配卡過強、快速碾壓怪物時，系統主動強化怪物抗性、提升怪獸移速與精英刷新率，增加挑戰張力。
 * - 當玩家處於逆境瀕死時：給予適度補給救援。
 */
export class FiveLevelMilestoneRule implements IBalanceRule {
  public readonly id = 'FIVE_LEVEL_MILESTONE_RULE';

  public evaluate(
    metrics: PacingMetrics,
    modifiers: PacingModifiers,
    currentState: PacingState
  ): PacingState | void {
    const milestoneTier = Math.floor(metrics.level / 5);

    // 1. 雙向平衡守門：當玩家過強（快速升等、滿血碾壓），給予對應怪物強化與戰術反壓
    const isPlayerSnowballing = metrics.timeSinceLevelUp < 12 && metrics.playerHpRatio > 0.75;
    if (isPlayerSnowballing && metrics.level >= 5) {
      // 依里程碑層級增加怪獸血量與強度（最高提升 +35% 血量、+12% 移速）
      const hpScaling = Math.min(0.35, 0.12 + milestoneTier * 0.015);
      const speedScaling = Math.min(0.12, 0.04 + milestoneTier * 0.006);

      modifiers.mobHpMultiplier = Math.max(modifiers.mobHpMultiplier, 1.0 + hpScaling);
      modifiers.mobSpeedMultiplier = Math.max(modifiers.mobSpeedMultiplier, 1.0 + speedScaling);
      modifiers.eliteSpawnChanceMultiplier = Math.max(modifiers.eliteSpawnChanceMultiplier, 1.30);
      modifiers.expDropMultiplier = Math.min(modifiers.expDropMultiplier, 0.90); // 抑制連續秒殺跳窗

      return 'MILESTONE_CHALLENGE';
    }

    // 2. 當玩家處於逆境時，提供適度生機
    if (metrics.playerHpRatio < 0.30) {
      modifiers.heartDropBonusRate = Math.max(modifiers.heartDropBonusRate, 0.05);
      modifiers.magnetRadiusMultiplier = Math.max(modifiers.magnetRadiusMultiplier, 1.15);
    }

    return currentState;
  }
}
