export type PacingState =
  | 'FLOW'
  | 'SLOG_ASSIST'
  | 'BOSS_CONVERGENCE'
  | 'PINCH_RESCUE'
  | 'BOSS_TACTICAL_DEFENSE'
  | 'MILESTONE_CHALLENGE';

export interface PacingMetrics {
  timeSinceLevelUp: number;
  bossCombatTime: number;
  bossHpRatio: number;
  playerHpRatio: number;
  stage: number;
  level: number;
}

export interface PacingModifiers {
  expDropMultiplier: number;
  magnetRadiusMultiplier: number;
  bossDamageTakenMultiplier: number;
  playerAttackSpeedMultiplier: number;
  heartDropBonusRate: number;
  mobHpMultiplier: number;
  mobSpeedMultiplier: number;
  eliteSpawnChanceMultiplier: number;
}

export function createDefaultPacingModifiers(): PacingModifiers {
  return {
    expDropMultiplier: 1.0,
    magnetRadiusMultiplier: 1.0,
    bossDamageTakenMultiplier: 1.0,
    playerAttackSpeedMultiplier: 1.0,
    heartDropBonusRate: 0.0,
    mobHpMultiplier: 1.0,
    mobSpeedMultiplier: 1.0,
    eliteSpawnChanceMultiplier: 1.0,
  };
}
