import * as THREE from 'three';
import { TELEKINETIC_MUZZLE_OFFSET } from '../../../sdk/snek-pet/index.ts';
import { Hero3D } from '../entities/Hero3D.ts';
import { Monster3D } from '../entities/Monster3D.ts';
import { ProjectileConfig } from '../types.ts';

export class CombatSystem {
  public attackTimer: number = 0;
  private projectileIdCounter: number = 0;
  public readonly maxLockRange: number;

  constructor(maxLockRange: number = 12.0) {
    this.maxLockRange = maxLockRange;
  }

  /**
   * 搜尋距離主角最近且存活的怪物目標
   */
  public findNearestTarget(heroPos: THREE.Vector3, monsters: Monster3D[]): Monster3D | null {
    let nearest: Monster3D | null = null;
    let minDist = this.maxLockRange;

    for (let i = 0; i < monsters.length; i++) {
      const m = monsters[i];
      if (m.isDead) continue;
      const mPos = m.getPosition();
      const dist = Math.hypot(mPos.x - heroPos.x, mPos.z - heroPos.z);
      if (dist < minDist) {
        minDist = dist;
        nearest = m;
      }
    }

    return nearest;
  }

  /**
   * 執行邊走邊射念力鎖定與開火判定，回傳本幀新產生的投射物配置陣列
   */
  public updateAutoAimAndFire(
    delta: number,
    hero: Hero3D,
    monsters: Monster3D[],
    isMoving: boolean,
    rng: () => number = Math.random
  ): ProjectileConfig[] {
    const heroPos = hero.getPosition();
    const nearest = this.findNearestTarget(heroPos, monsters);
    if (!nearest) return [];

    const nPos = nearest.getPosition();
    hero.faceTarget(nPos.x, nPos.z);

    const weapon = hero.getCurrentWeapon();
    const effectiveAttackSpeed = hero.stats.attackSpeed * weapon.attackSpeedMultiplier;

    this.attackTimer -= delta;
    if (this.attackTimer > 0) {
      return [];
    }

    this.attackTimer = 1.0 / Math.max(0.2, effectiveAttackSpeed);
    hero.swingWeapon();

    const muzzleX = heroPos.x + TELEKINETIC_MUZZLE_OFFSET.x;
    const muzzleZ = heroPos.z + TELEKINETIC_MUZZLE_OFFSET.z;
    const dx = nPos.x - muzzleX;
    const dz = nPos.z - muzzleZ;
    const len = Math.hypot(dx, dz);

    if (len <= 0.01) return [];

    const baseAngle = Math.atan2(dx, dz);
    const shotCount = weapon.shotCount ?? 1;
    const spreadAngle = weapon.spreadAngle ?? 0;

    // 站立不動提供 +8% 精準暴擊獎勵，移動中維持 100% 射速
    const effectiveCritChance = hero.stats.critChance + (isMoving ? 0 : 0.08);
    const isCrit = rng() < effectiveCritChance;
    const totalAtk = hero.stats.atk + weapon.atkBonus;
    const dmg = Math.round(totalAtk * (isCrit ? hero.stats.critMultiplier : 1.0));

    const spawnedConfigs: ProjectileConfig[] = [];

    for (let s = 0; s < shotCount; s++) {
      const offsetIndex = shotCount > 1 ? s - (shotCount - 1) / 2 : 0;
      const angle = baseAngle + offsetIndex * (spreadAngle / Math.max(1, shotCount - 1));
      const vx = Math.sin(angle);
      const vz = Math.cos(angle);

      this.projectileIdCounter++;
      spawnedConfigs.push({
        id: `proj_${this.projectileIdCounter}`,
        x: muzzleX + vx * 0.35,
        z: muzzleZ + vz * 0.35,
        vx,
        vz,
        damage: dmg,
        isCrit,
        life: 0.95,
        maxLife: 0.95,
        modelUrl: isCrit
          ? './assets/dungeon3d/kenney/blaster-kit/grenade-a.glb'
          : weapon.projectileModelUrl,
        pierceLeft: weapon.pierceCount ?? 0,
        explosionRadius: weapon.explosionRadius ?? 0,
      });
    }

    return spawnedConfigs;
  }
}
