/**
 * Sector index (0..7) -> official turnaround sprite index (0000..0007):
 * Sector 0 (South / Front)      -> 7 (body_armless_0007)
 * Sector 1 (South-East)         -> 6 (body_armless_0006)
 * Sector 2 (East / Side-Right)  -> 5 (body_armless_0005)
 * Sector 3 (North-East)         -> 4 (body_armless_0004)
 * Sector 4 (North / Back)       -> 3 (body_armless_0003)
 * Sector 5 (North-West)         -> 2 (body_armless_0002)
 * Sector 6 (West / Side-Left)   -> 1 (body_armless_0001)
 * Sector 7 (South-West)         -> 0 (body_armless_0000)
 */
const SECTOR_TO_ASSET_INDEX: number[] = [7, 6, 5, 4, 3, 2, 1, 0];

type ArmTextureKey =
  | 'front_L'
  | 'front_R'
  | 'outer_L'
  | 'outer_R'
  | 'inner_L'
  | 'inner_R'
  | 'side_L'
  | 'side_R';

interface RigSectorLayout {
  leftShoulder: [number, number, number];
  rightShoulder: [number, number, number];
  leftArmKey: ArmTextureKey;
  rightArmKey: ArmTextureKey;
  leftVisible: boolean;
  rightVisible: boolean;
  hasFrontFace: boolean;
  useHeadOnlyOnExpression?: boolean;
  neckPos: [number, number, number];
  faceFlipX: number;
}

