export class Hero3D {
  public group: THREE.Group;
  public stats: HeroStats;

  // 2.5D Rig Hierarchy
  private rigGroup: THREE.Group;
  private heroMesh: THREE.Mesh;
  private leftArmMesh: THREE.Mesh;
  private rightArmMesh: THREE.Mesh;
  private headMesh: THREE.Mesh;
  private shadowMesh: THREE.Mesh;

  // 3D Kenney Blaster Weapon Hierarchy (Telekinetic Floating Mount at Upper-Right of Head)
  public weaponMount: TelekineticWeaponMount3D;
  public emoteBubble: SnekEmoteBubble3D;
  private weaponOrbitGroup: THREE.Group;
  private weaponModelHolder: THREE.Group;
  private psychicOuterRing: THREE.Mesh;
  private psychicInnerRing: THREE.Mesh;
  private currentWeaponTierIndex: number = 0;
  private customWeaponConfig: WeaponTierConfig | null = null;

  // Materials
  private turnaroundMaterials: THREE.MeshStandardMaterial[] = []; // Indexed by sector 0..7 (armless body)
  private headlessMaterials: Map<number, THREE.MeshStandardMaterial> = new Map(); // Sector 0, 1, 7 headless body
  private faceMaterials: THREE.MeshStandardMaterial[] = []; // 12 official expressions (face_0000..face_0011)
  private armMaterials: Record<ArmTextureKey, THREE.MeshStandardMaterial> = {} as Record<
    ArmTextureKey,
    THREE.MeshStandardMaterial
  >;

  private currentDirIndex: number = 0; // Sector 0..7
  private currentFaceIndex: number = 7; // Default chill face (SNEK_0007)
  private expressionTimer: number = 0;
  private celebrationTimer: number = 0;
  private hurtAnimTimer: number = 0;
  private swingComboCount: number = 0;

  // Optional 3D GLB Model and Animation Controller
  private glbModel: THREE.Object3D | null = null;
  private animController: ModelAnimationController | null = null;
  public isGLBLoaded: boolean = false;

  private isSwinging: boolean = false;
  private swingTimer: number = 0;
  private walkTime: number = 0;
  private invulnerableTimer: number = 0;

  constructor(scene: THREE.Scene, initialStats?: Partial<HeroStats>) {
    this.stats = {
      maxHp: 100,
      hp: 100,
      atk: 25,
      def: 5,
      critChance: 0.2,
      critMultiplier: 2.0,
      attackSpeed: 2.2,
      moveSpeed: 6.5,
      gold: 0,
      kills: 0,
      floor: 1,
      ...initialStats,
    };

    this.group = new THREE.Group();
    scene.add(this.group);

    // 1. Dynamic Ground Shadow Ellipse
    const shadowGeo = new THREE.CircleGeometry(0.55, 24);
    const shadowMat = new THREE.MeshBasicMaterial({
      color: 0x000000,
      transparent: true,
      opacity: 0.42,
      depthWrite: false,
    });
    this.shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
    this.shadowMesh.rotation.x = -Math.PI / 2;
    this.shadowMesh.position.y = 0.02;
    this.group.add(this.shadowMesh);

    // 2. Rig Container tilted towards the 45-degree isometric camera
    this.rigGroup = new THREE.Group();
    this.rigGroup.position.y = 1.0;
    this.rigGroup.rotation.x = -0.32;
    this.group.add(this.rigGroup);

    const texLoader = new THREE.TextureLoader();
    const createSpriteMat = (url: string): THREE.MeshStandardMaterial => {
      const mat = new THREE.MeshStandardMaterial({
        transparent: true,
        alphaTest: 0.05,
        roughness: 0.55,
        metalness: 0.02,
        side: THREE.DoubleSide,
      });
      const tex = texLoader.load(url, (t) => {
        t.colorSpace = THREE.SRGBColorSpace;
        mat.needsUpdate = true;
      });
      mat.map = tex;
      return mat;
    };

    // 3. Load 8-directional armless bodies mapped by sector (0..7)
    for (let sector = 0; sector < 8; sector++) {
      const assetIdx = SECTOR_TO_ASSET_INDEX[sector];
      const padIdx = assetIdx.toString().padStart(4, '0');
      this.turnaroundMaterials.push(
        createSpriteMat(`./assets/dungeon3d/snek/body_armless_${padIdx}.webp`)
      );
    }

    // 4. Load headless front/quarter bodies (for Sector 0 -> 0007, Sector 1 -> 0006, Sector 7 -> 0000)
    this.headlessMaterials.set(
      0,
      createSpriteMat('./assets/dungeon3d/snek/body_headless_0007.webp')
    );
    this.headlessMaterials.set(
      1,
      createSpriteMat('./assets/dungeon3d/snek/body_headless_0006.webp')
    );
    this.headlessMaterials.set(
      7,
      createSpriteMat('./assets/dungeon3d/snek/body_headless_0000.webp')
    );

    // 5. Load 12 official Face expressions (face_0000 .. face_0011)
    for (let i = 0; i < 12; i++) {
      const padIdx = i.toString().padStart(4, '0');
      this.faceMaterials.push(
        createSpriteMat(`./assets/dungeon3d/snek/face_${padIdx}.webp`)
      );
    }

    // 6. Body Mesh
    const heroGeo = new THREE.PlaneGeometry(1.85, 2.0);
    this.heroMesh = new THREE.Mesh(heroGeo, this.turnaroundMaterials[0]);
    this.rigGroup.add(this.heroMesh);

    // 7. Articulated Left & Right Arm Meshes (pivoted at shoulder joint (600, 100) on 1200x1200 canvas)
    const armKeys: ArmTextureKey[] = [
      'front_L',
      'front_R',
      'outer_L',
      'outer_R',
      'inner_L',
      'inner_R',
      'side_L',
      'side_R',
    ];
    for (const key of armKeys) {
      this.armMaterials[key] = createSpriteMat(`./assets/dungeon3d/snek/arm_${key}.webp`);
    }

    const armW = 1.376;
    const armH = 1.286;
    const leftArmGeo = new THREE.PlaneGeometry(armW, armH);
    leftArmGeo.translate(0, -0.536, 0); // Shift geometry so shoulder pivot (600, 100) is at local origin (0,0,0)
    this.leftArmMesh = new THREE.Mesh(leftArmGeo, this.armMaterials.front_L);
    this.rigGroup.add(this.leftArmMesh);

    const rightArmGeo = new THREE.PlaneGeometry(armW, armH);
    rightArmGeo.translate(0, -0.536, 0); // Shift geometry so shoulder pivot (600, 100) is at local origin (0,0,0)
    this.rightArmMesh = new THREE.Mesh(rightArmGeo, this.armMaterials.front_R);
    this.rigGroup.add(this.rightArmMesh);

    // 8. Articulated Head / Expression Mesh (pivoted at neck)
    const headW = 1.28;
    const headH = 0.875;
    const headGeo = new THREE.PlaneGeometry(headW, headH);
    headGeo.translate(0, 0.259, 0); // Shift geometry so neck joint is at local origin (0,0,0)
    this.headMesh = new THREE.Mesh(headGeo, this.faceMaterials[7]);
    this.rigGroup.add(this.headMesh);

    // 9. Telekinetic 3D Blaster Weapon Mount & Snek Emote Bubble via SnekPetSDK
    this.weaponMount = new TelekineticWeaponMount3D(this.group);
    this.emoteBubble = new SnekEmoteBubble3D(this.group);
    this.weaponOrbitGroup = this.weaponMount.orbitGroup;
    this.weaponModelHolder = this.weaponMount.modelHolder;
    this.psychicOuterRing = this.weaponMount.psychicOuterRing;
    this.psychicInnerRing = this.weaponMount.psychicInnerRing;

    this.setWeaponTier(0);

    // Apply initial sector layout (Sector 0: Front)
    this.applySectorLayout(0);

    // Initial world position
    this.group.position.set(0, 0, 4);
  }

  public showEmote(emote: SnekEmoteType, duration: number = 1.6): void {
    this.emoteBubble.showEmote(emote, duration);
  }

  public applyResolvedCombatProfile(profile: ResolvedSnekCombatProfile): void {
    this.stats.maxHp = profile.stats.hp;
    this.stats.hp = Math.min(this.stats.hp, this.stats.maxHp);
    this.stats.atk = profile.stats.atk;
    this.stats.def = profile.stats.def;
    this.stats.moveSpeed = profile.stats.speed;
    this.stats.critChance = profile.critChance;
    this.stats.critMultiplier = profile.critMultiplier;
    this.stats.weaponTier = profile.weapon.tier;

    const plusLabel = profile.weapon.upgradeLevel > 0 ? ` +${profile.weapon.upgradeLevel}` : '';
    this.customWeaponConfig = {
      tier: profile.weapon.tier,
      name: `${profile.weapon.name}${plusLabel}`,
      modelUrl: profile.weapon.modelUrl,
      iconUrl: profile.weapon.iconUrl,
      projectileModelUrl: profile.weapon.projectileModelUrl,
      atkBonus: 0,
      attackSpeedMultiplier: profile.attackSpeed / 2.0,
      shotCount: profile.shotCount,
      spreadAngle: profile.spreadAngle,
      pierceCount: profile.pierceCount,
      explosionRadius: profile.explosionRadius,
    };
    this.weaponMount.loadWeaponModel(profile.weapon.modelUrl);
  }

  public getCurrentWeapon(): WeaponTierConfig {
    return this.customWeaponConfig || WEAPON_TIERS[this.currentWeaponTierIndex] || WEAPON_TIERS[0];
  }

  public setWeaponTier(tierIdx: number): WeaponTierConfig {
    const clampedIdx = Math.max(0, Math.min(WEAPON_TIERS.length - 1, tierIdx));
    this.currentWeaponTierIndex = clampedIdx;
    this.stats.weaponTier = clampedIdx + 1;
    this.customWeaponConfig = null;
    const tierCfg = WEAPON_TIERS[clampedIdx];
    this.weaponMount.loadWeaponModel(tierCfg.modelUrl);
    return tierCfg;
  }

  public upgradeWeapon(): WeaponTierConfig {
    this.showEmote('stars', 1.8);
    return this.setWeaponTier(this.currentWeaponTierIndex + 1);
  }

  public setGLBModel(model: THREE.Object3D, controller?: ModelAnimationController): void {
    if (this.glbModel) {
      this.group.remove(this.glbModel);
    }
    this.glbModel = model;
    this.animController = controller || null;
    this.isGLBLoaded = true;
    this.rigGroup.visible = false;
    model.scale.set(0.85, 0.85, 0.85);
    this.group.add(model);
  }

  /**
   * Updates body material, shoulder positions, arm textures, and head visibility for a given 8-direction sector (0..7)
   */
  private applySectorLayout(sector: number): void {
    this.currentDirIndex = sector;
    const layout = SECTOR_RIG_LAYOUT[sector] || SECTOR_RIG_LAYOUT[0];

    this.leftArmMesh.position.set(...layout.leftShoulder);
    this.rightArmMesh.position.set(...layout.rightShoulder);
    this.leftArmMesh.material = this.armMaterials[layout.leftArmKey];
    this.rightArmMesh.material = this.armMaterials[layout.rightArmKey];
    this.leftArmMesh.visible = layout.leftVisible;
    this.rightArmMesh.visible = layout.rightVisible;

    const showHeadMesh =
      layout.hasFrontFace &&
      this.headlessMaterials.has(sector) &&
      (!layout.useHeadOnlyOnExpression || this.expressionTimer > 0);

    if (showHeadMesh) {
      this.heroMesh.material = this.headlessMaterials.get(sector)!;
      this.headMesh.visible = true;
      this.headMesh.position.set(...layout.neckPos);
      this.headMesh.scale.x = layout.faceFlipX;
      this.headMesh.material = this.faceMaterials[this.currentFaceIndex] || this.faceMaterials[7];
    } else {
      this.heroMesh.material = this.turnaroundMaterials[sector] || this.turnaroundMaterials[0];
      this.headMesh.visible = false;
    }
  }

  public setFaceExpression(faceIndex: number, duration: number = 0.4): void {
    if (faceIndex >= 0 && faceIndex < this.faceMaterials.length) {
      this.currentFaceIndex = faceIndex;
      this.expressionTimer = duration;
      this.applySectorLayout(this.currentDirIndex);
    }
  }

  /**
   * Calculate 8-direction sector index (0 to 7) from velocity vector (vx, vz)
   * Three.js coordinates: +X is East, -X is West, +Z is South (towards camera), -Z is North (away)
   */
  private getDirectionIndex(vx: number, vz: number): number {
    let angle = Math.atan2(vx, vz); // 0 is South, PI/2 is East, PI is North, -PI/2 is West
    if (angle < 0) {
      angle += Math.PI * 2;
    }
    const sector = Math.PI / 4;
    return Math.round(angle / sector) % 8;
  }

  public move(vx: number, vz: number, delta: number): void {
    const isMoving = Math.hypot(vx, vz) > 0.01;

    if (this.isGLBLoaded && this.glbModel) {
      if (isMoving) {
        this.animController?.play('walk');
        this.walkTime += delta * 14;
        const bob = Math.abs(Math.sin(this.walkTime)) * 0.08;
        this.glbModel.position.y = bob;
        this.glbModel.rotation.z = Math.sin(this.walkTime) * 0.08;

        const targetAngle = Math.atan2(vx, vz);
        let diff = targetAngle - this.glbModel.rotation.y;
        while (diff < -Math.PI) diff += Math.PI * 2;
        while (diff > Math.PI) diff -= Math.PI * 2;
        this.glbModel.rotation.y += diff * Math.min(1.0, delta * 12);
      } else {
        this.animController?.play('idle');
        this.walkTime += delta * 3;
        const breathe = Math.sin(this.walkTime) * 0.02;
        this.glbModel.position.y = breathe;
        this.glbModel.rotation.z = 0;
      }
    } else {
      if (isMoving) {
        this.weaponOrbitGroup.rotation.y = Math.atan2(vx, vz);
        const nextSector = this.getDirectionIndex(vx, vz);
        if (nextSector !== this.currentDirIndex) {
          this.applySectorLayout(nextSector);
        }

        // Slither bobbing
        this.walkTime += delta * 14;
        const bob = Math.abs(Math.sin(this.walkTime)) * 0.12;
        this.rigGroup.position.y = 1.0 + bob;
        this.shadowMesh.scale.setScalar(1 - bob * 0.35);

        // Dynamic slight tilt into movement
        this.rigGroup.rotation.z = -vx * 0.1;

        // Articulated arm swing while walking (if not mid-attack raise)
        if (!this.isSwinging && this.hurtAnimTimer <= 0 && this.celebrationTimer <= 0) {
          const swing = Math.sin(this.walkTime) * 0.55; // +/- 32 degrees shoulder swing
          this.leftArmMesh.rotation.z = swing - 0.15;
          this.rightArmMesh.rotation.z = -swing + 0.15;
          this.headMesh.rotation.z = Math.sin(this.walkTime * 0.5) * 0.06;
        }
      } else {
        // Idle breathing & celebration bounce
        this.walkTime += delta * 3.2;
        const bounce = this.celebrationTimer > 0 ? Math.abs(Math.sin(this.celebrationTimer * 12)) * 0.12 : 0;
        const breathe = Math.sin(this.walkTime) * 0.03;
        this.rigGroup.position.y = 1.0 + breathe + bounce;
        this.rigGroup.rotation.z = 0;
        this.shadowMesh.scale.setScalar(1.0 - bounce * 0.25);

        if (!this.isSwinging && this.hurtAnimTimer <= 0 && this.celebrationTimer <= 0) {
          const idleArm = Math.sin(this.walkTime) * 0.08;
          this.leftArmMesh.rotation.z = -0.06 + idleArm;
          this.rightArmMesh.rotation.z = 0.06 - idleArm;
          this.headMesh.rotation.z = Math.sin(this.walkTime * 0.5) * 0.03;
        }
      }
    }
  }

  public faceTarget(targetX: number, targetZ: number): void {
    const dx = targetX - this.group.position.x;
    const dz = targetZ - this.group.position.z;

    if (this.isGLBLoaded && this.glbModel) {
      if (Math.hypot(dx, dz) > 0.05) {
        this.glbModel.rotation.y = Math.atan2(dx, dz);
      }
    } else {
      if (Math.hypot(dx, dz) > 0.05) {
        const aimAngle = Math.atan2(dx, dz);
        this.weaponOrbitGroup.rotation.y = aimAngle;
        const nextSector = this.getDirectionIndex(dx, dz);
        if (nextSector !== this.currentDirIndex) {
          this.applySectorLayout(nextSector);
        }
      }
    }
  }

  public swingWeapon(): void {
    this.isSwinging = true;
    this.swingTimer = 0.28;
    this.swingComboCount++;

    // Alternate between fierce official battle faces:
    // 10 = clenched teeth battle rage, 8 = open-mouth fang attack, 11 = angry glare, 2 = confident grin
    const attackFaces = [10, 8, 11, 2];
    const chosenFace = attackFaces[this.swingComboCount % attackFaces.length];
    this.setFaceExpression(chosenFace, 0.35);

    if (this.isGLBLoaded && this.animController) {
      this.animController.play('attack');
    }
  }

  public update(delta: number): void {
    if (this.isGLBLoaded) {
      this.animController?.update(delta);
    } else {
      // Telekinetic floating hover & psychic ring rotation at upper-right of head
      const hoverY = Math.sin(this.walkTime * 0.7) * 0.1;
      const hoverTilt = Math.cos(this.walkTime * 0.7) * 0.08;
      this.weaponOrbitGroup.position.set(0.88, 2.02 + hoverY, 0.15);
      this.weaponModelHolder.rotation.z = hoverTilt;
      this.psychicOuterRing.rotation.z += delta * 2.8;
      this.psychicInnerRing.rotation.z -= delta * 4.2;

      // 1. Expression timer decay back to chill smile (face 7)
      if (this.expressionTimer > 0) {
        this.expressionTimer -= delta;
        if (this.expressionTimer <= 0) {
          this.currentFaceIndex = 7;
          this.applySectorLayout(this.currentDirIndex);
        }
      }

      // 2. Hurt / Celebration arm timers
      if (this.hurtAnimTimer > 0) {
        this.hurtAnimTimer -= delta;
        // Both arms flung up in surprise
        this.leftArmMesh.rotation.z = -1.75;
        this.rightArmMesh.rotation.z = 1.75;
        this.headMesh.rotation.z = Math.sin(this.hurtAnimTimer * 40) * 0.12;
      } else if (this.celebrationTimer > 0) {
        this.celebrationTimer -= delta;
        // 歡呼情緒：頭部微晃與愛心表情，雙手自然垂放不舉手
        const nod = Math.sin(this.celebrationTimer * 16) * 0.08;
        this.leftArmMesh.rotation.z = -0.06 + nod * 0.4;
        this.rightArmMesh.rotation.z = 0.06 - nod * 0.4;
        this.headMesh.rotation.z = nod;
      } else if (this.isSwinging) {
        // 3. Telekinetic firing pulse & recoil animation
        this.swingTimer -= delta;
        if (this.swingTimer <= 0) {
          this.isSwinging = false;
          this.rigGroup.scale.set(1.0, 1.0, 1.0);
          this.headMesh.rotation.z = 0;
          this.weaponModelHolder.position.z = 0;
          this.weaponModelHolder.rotation.x = 0;
          this.psychicOuterRing.scale.setScalar(1.0);
          this.psychicInnerRing.scale.setScalar(1.0);
        } else {
          // Progress t from 0 (start of shot) to 1 (end of shot)
          const t = 1.0 - this.swingTimer / 0.28;
          const arc = Math.sin(t * Math.PI); // Peaks at 1.0 mid-shot
          const punch = arc * 0.06;
          this.rigGroup.scale.set(1.0 + punch, 1.0 + punch, 1.0);

          // 3D Floating Blaster telekinetic recoil kick & psychic ring flare
          this.weaponModelHolder.position.z = -arc * 0.24;
          this.weaponModelHolder.rotation.x = -arc * 0.32;
          this.psychicOuterRing.scale.setScalar(1.0 + arc * 0.38);
          this.psychicInnerRing.scale.setScalar(1.0 + arc * 0.5);

          // Subtle psychic channeling hand gesture on right/visible arm
          const raiseRight =
            this.currentDirIndex === 2
              ? true
              : this.currentDirIndex === 6
                ? false
                : true;

          if (raiseRight) {
            this.rightArmMesh.rotation.z = 0.25 + arc * 0.55;
            this.headMesh.rotation.z = -arc * 0.05;
          } else {
            this.leftArmMesh.rotation.z = -0.25 - arc * 0.55;
            this.headMesh.rotation.z = arc * 0.05;
          }
        }
      }
    }

    // Invulnerability timer & damage flash across all rig materials
    if (this.invulnerableTimer > 0) {
      this.invulnerableTimer -= delta;
      const flash = Math.floor(this.invulnerableTimer * 14) % 2 === 0;
      const hex = flash ? 0xff4444 : 0xffffff;
      this.setRigTint(hex);
    } else {
      this.setRigTint(0xffffff);
    }

    this.emoteBubble.update(delta);
  }

  private setRigTint(hex: number): void {
    this.turnaroundMaterials.forEach((m) => m.color.setHex(hex));
    this.headlessMaterials.forEach((m) => m.color.setHex(hex));
    this.faceMaterials.forEach((m) => m.color.setHex(hex));
    Object.values(this.armMaterials).forEach((m) => m.color.setHex(hex));
  }

  public takeDamage(damage: number): boolean {
    if (this.invulnerableTimer > 0) return false;

    const actualDamage = Math.max(1, Math.round(damage - this.stats.def * 0.3));
    this.stats.hp = Math.max(0, this.stats.hp - actualDamage);
    this.invulnerableTimer = 0.6;
    this.hurtAnimTimer = 0.38;

    // Switch to shocked / hurt / crying official expression (0 = shocked wide eyes, 4 = hurt tongue, 1 = crying)
    const hurtFaces = [0, 4, 1];
    this.setFaceExpression(hurtFaces[Math.floor(Math.random() * hurtFaces.length)], 0.55);
    this.showEmote('angry', 1.2);

    return true;
  }

  public heal(amount: number): void {
    this.stats.hp = Math.min(this.stats.maxHp, this.stats.hp + amount);
    this.celebrate(0.85);
  }

  public celebrate(durationSec: number = 1.0): void {
    this.celebrationTimer = durationSec;
    this.setFaceExpression(6, durationSec);
    this.showEmote('heart', durationSec);
  }

  public isAlive(): boolean {
    return this.stats.hp > 0;
  }

  public getPosition(): THREE.Vector3 {
    return this.group.position;
  }

  public setPosition(x: number, z: number): void {
    this.group.position.set(x, 0, z);
  }

  public destroy(): void {
    this.group.traverse((obj) => {
      if (obj instanceof THREE.Mesh) {
        obj.geometry?.dispose();
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material?.dispose();
        }
      }
    });
    this.turnaroundMaterials.forEach((m) => m.dispose());
    this.headlessMaterials.forEach((m) => m.dispose());
    this.faceMaterials.forEach((m) => m.dispose());
    Object.values(this.armMaterials).forEach((m) => m.dispose());
    this.turnaroundMaterials = [];
    this.headlessMaterials.clear();
    this.faceMaterials = [];
  }
}
