import { ISkillCard, SkillCardContext } from '../ISkillCard.ts';

export class WhaleMagnetCard implements ISkillCard {
  public readonly id = 'WHALE_MAGNET';
  public readonly title = '鏈上巨鯨吸籌';
  public readonly badge = '籌碼沉澱';
  public readonly category = 'STATS';
  public readonly iconKey = 'magnet';
  public readonly maxLevel = 8;
  public readonly financeTerm = '【巨鯨吸籌 (Whale Accumulation)】實力大戶在恐慌拋售潮中默默吃進廉價籌碼。';

  public getDescription(currentLevel: number): string {
    const next = currentLevel + 1;
    return `體量黑洞引力！經驗水晶自動磁吸半徑提升至 ${65 + next * 25}px`;
  }

  public isEligible(context: SkillCardContext): boolean {
    const current = context.engine.skillLevels?.get(this.id) ?? 0;
    return current < this.maxLevel;
  }

  public apply(context: SkillCardContext, nextLevel: number): void {
    if (nextLevel === 1) {
      context.engine.magnetRadius = (context.engine.magnetRadius || 65) * 2;
    } else {
      context.engine.magnetRadius = (context.engine.magnetRadius || 130) + 25;
    }
  }
}
