import { SaveManager } from '../save/SaveManager.ts';

export interface TalentApplierHost {
  weaponManager: {
    venom: { count?: number; cooldown?: number; upgrade: () => void };
    orbiter: { count?: number; speed?: number; upgrade: () => void };
  };
  damageMultiplier: number;
  speed: number;
  hp: number;
  maxHp: number;
  damageReduction: number;
  magnetRadius: number;
  hasCompoundInterest: boolean;
  kills: number;
  enemies: Array<{ x: number; y: number; isBoss?: boolean; type?: string }>;
  expGems: Array<{ id: string; x: number; y: number; value: number; tier?: 'NORMAL' | 'ELITE' | 'BOSS' }>;
  particleSystem: { emitDeath: (x: number, y: number) => void };
  soundManager: { playHighScore: () => void };
  callbacks: {
    onHpChange: (hp: number, maxHp: number) => void;
    onKillsChange: (kills: number) => void;
  };
  resume: () => void;
}

export class TalentApplier {
  public static apply(host: TalentApplierHost, upgradeId: string): void {
    if (upgradeId === 'FED_QE_PIVOT' || upgradeId === 'MEGA_BURN') {
      for (const e of host.enemies) {
        if (!e.isBoss) {
          host.particleSystem.emitDeath(e.x, e.y);
          const val = e.type === 'BEAR' ? 3 : (e.type === 'LIQUIDATION_REAPER' ? 5 : 1);
          host.expGems.push({
            id: `gem_${Math.random()}`,
            x: e.x,
            y: e.y,
            value: val,
            tier: val >= 3 ? 'ELITE' : 'NORMAL',
          });
        }
      }
      host.kills += host.enemies.filter((e) => !e.isBoss).length;
      host.enemies = host.enemies.filter((e) => e.isBoss);
      host.callbacks.onKillsChange(host.kills);
      host.soundManager.playHighScore();
    }

    if (typeof (host as any).level === 'number') {
      SaveManager.getInstance().saveLevelCheckpoint({
        level: (host as any).level,
        stage: (host as any).stage ?? 1,
        hp: host.hp,
        maxHp: host.maxHp,
        speed: host.speed,
        damageReduction: host.damageReduction,
        damageMultiplier: host.damageMultiplier,
        magnetRadius: host.magnetRadius,
        hasCompoundInterest: host.hasCompoundInterest,
        weapons: {
          venomCount: host.weaponManager.venom.count ?? 1,
          venomCooldown: host.weaponManager.venom.cooldown ?? 420,
          orbitCount: host.weaponManager.orbiter.count ?? 0,
          orbitSpeed: host.weaponManager.orbiter.speed ?? 0,
        },
        kills: host.kills,
        elapsedTime: Math.floor((host as any).elapsedTime || 0),
      });
    }
    (host as any).balanceDirector?.notifyLevelUp();

    host.resume();
  }
}
