import * as THREE from 'three';
import { MonsterConfig } from '../types.ts';
import { GLTFModelLoader } from '../core/GLTFModelLoader.ts';

export class Monster3D {
  public group: THREE.Group;
  public config: MonsterConfig;
  public isDead: boolean = false;

  private visualHolder: THREE.Group;
  private fallbackGroup: THREE.Group;
  private mesh: THREE.Mesh;
  private material: THREE.MeshStandardMaterial;
  private glbMaterials: Array<{
    mat: THREE.MeshStandardMaterial;
    origColor: number;
    origEmissive: number;
  }> = [];

  private hpBarGroup: THREE.Group;
  private hpBarFill: THREE.Mesh;

  private originalColor: number;
  private flashTimer: number = 0;
  private jumpTimer: number = Math.random() * Math.PI * 2;
  private knockbackVec: THREE.Vector3 = new THREE.Vector3();

  constructor(scene: THREE.Scene, config: MonsterConfig, posX: number, posZ: number) {
    this.config = { ...config };
    this.originalColor = config.color;

    this.group = new THREE.Group();
    scene.add(this.group);
    this.group.position.set(posX, 0, posZ);

    // Ground shadow under monster
    const shadowGeo = new THREE.CircleGeometry(config.size * 0.85, 18);
    const shadowMat = new THREE.MeshBasicMaterial({
      color: 0x000000,
      transparent: true,
      opacity: 0.38,
      depthWrite: false,
    });
    const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
    shadowMesh.rotation.x = -Math.PI / 2;
    shadowMesh.position.y = 0.02;
    this.group.add(shadowMesh);

    // Visual holder for bouncy walk / squash & stretch
    this.visualHolder = new THREE.Group();
    this.group.add(this.visualHolder);

    // Fallback procedural mesh (used immediately before GLB resolves or in unit tests)
    this.fallbackGroup = new THREE.Group();
    this.visualHolder.add(this.fallbackGroup);

    if (config.type === 'GOLEM_BOSS') {
      const geo = new THREE.BoxGeometry(config.size * 1.4, config.size * 1.8, config.size * 1.4);
      this.material = new THREE.MeshStandardMaterial({
        color: config.color,
        roughness: 0.9,
        metalness: 0.2,
      });
      this.mesh = new THREE.Mesh(geo, this.material);
      this.mesh.position.y = (config.size * 1.8) / 2;
    } else {
      const geo = new THREE.SphereGeometry(config.size, 14, 14);
      this.material = new THREE.MeshStandardMaterial({
        color: config.color,
        roughness: 0.25,
        metalness: 0.3,
        emissive: config.color,
        emissiveIntensity: 0.2,
      });
      this.mesh = new THREE.Mesh(geo, this.material);
      this.mesh.position.y = config.size;
    }
    this.fallbackGroup.add(this.mesh);

    // Fallback cute eyes
    const eyeMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const pupilMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
    const eyeSize = config.size * 0.22;

    const leftEye = new THREE.Mesh(new THREE.SphereGeometry(eyeSize, 6, 6), eyeMat);
    leftEye.position.set(-config.size * 0.35, config.size * 1.15, config.size * 0.8);
    const leftPupil = new THREE.Mesh(new THREE.SphereGeometry(eyeSize * 0.5, 6, 6), pupilMat);
    leftPupil.position.set(-config.size * 0.35, config.size * 1.15, config.size * 0.95);

    const rightEye = new THREE.Mesh(new THREE.SphereGeometry(eyeSize, 6, 6), eyeMat);
    rightEye.position.set(config.size * 0.35, config.size * 1.15, config.size * 0.8);
    const rightPupil = new THREE.Mesh(new THREE.SphereGeometry(eyeSize * 0.5, 6, 6), pupilMat);
    rightPupil.position.set(config.size * 0.35, config.size * 1.15, config.size * 0.95);

    this.fallbackGroup.add(leftEye, leftPupil, rightEye, rightPupil);

    // Load Kenney 3D Monster Model (Cube Pets / Graveyard Characters)
    const defaultModelUrl =
      config.modelUrl ||
      (config.type === 'GOLEM_BOSS'
        ? './assets/dungeon3d/kenney/cube-pets/animal-lion.glb'
        : './assets/dungeon3d/kenney/cube-pets/animal-fox.glb');
    this.loadMonsterGLB(defaultModelUrl);

    // Overhead HP Bar
    this.hpBarGroup = new THREE.Group();
    const hpBarY = config.type === 'GOLEM_BOSS' ? config.size * 2.35 : config.size * 2.25;
    this.hpBarGroup.position.set(0, hpBarY, 0);

    const barWidth = Math.max(1.0, config.size * 1.8);
    const barHeight = 0.13;

    const backGeo = new THREE.PlaneGeometry(barWidth, barHeight);
    const backMat = new THREE.MeshBasicMaterial({ color: 0x111622, side: THREE.DoubleSide });
    const backMesh = new THREE.Mesh(backGeo, backMat);
    this.hpBarGroup.add(backMesh);

    const fillGeo = new THREE.PlaneGeometry(barWidth, barHeight);
    fillGeo.translate(barWidth / 2, 0, 0);
    const fillMat = new THREE.MeshBasicMaterial({
      color: config.type === 'GOLEM_BOSS' ? 0xff9800 : 0xff3b30,
      side: THREE.DoubleSide,
    });
    this.hpBarFill = new THREE.Mesh(fillGeo, fillMat);
    this.hpBarFill.position.x = -barWidth / 2;
    this.hpBarGroup.add(this.hpBarFill);

    this.group.add(this.hpBarGroup);
  }

  private loadMonsterGLB(url: string): void {
    GLTFModelLoader.getInstance()
      .load(url)
      .then((gltf) => {
        if (this.isDead) return;
        const { scene: model } = GLTFModelLoader.getInstance().instantiate(gltf);

        // Compute bounding box so feet sit cleanly on y = 0 and height matches config.size * 1.9
        const box = new THREE.Box3().setFromObject(model);
        const size = new THREE.Vector3();
        const center = new THREE.Vector3();
        box.getSize(size);
        box.getCenter(center);

        const targetHeight =
          this.config.modelScale ||
          (this.config.type === 'GOLEM_BOSS' ? this.config.size * 2.1 : this.config.size * 1.85);
        const scale = targetHeight / Math.max(size.y, 0.01);
        model.scale.setScalar(scale);
        model.position.set(-center.x * scale, -box.min.y * scale, -center.z * scale);

        // Clone materials per monster instance so hit-flash doesn't flash other monsters
        model.traverse((child) => {
          if (child instanceof THREE.Mesh && child.material) {
            const clonedMat = (child.material as THREE.MeshStandardMaterial).clone();
            if (clonedMat.map) {
              clonedMat.map.colorSpace = THREE.SRGBColorSpace;
            }
            child.material = clonedMat;
            this.glbMaterials.push({
              mat: clonedMat,
              origColor: clonedMat.color ? clonedMat.color.getHex() : 0xffffff,
              origEmissive: clonedMat.emissive ? clonedMat.emissive.getHex() : 0x000000,
            });
          }
        });

        this.fallbackGroup.visible = false;
        this.visualHolder.add(model);
      })
      .catch(() => {
        // Fallback procedural mesh remains visible
      });
  }

  public update(delta: number, heroX: number, heroZ: number, camera: THREE.Camera): void {
    if (this.isDead) return;

    // Face camera for HP bar
    this.hpBarGroup.quaternion.copy(camera.quaternion);

    // Flash recovery
    if (this.flashTimer > 0) {
      this.flashTimer -= delta;
      if (this.flashTimer <= 0) {
        this.material.color.setHex(this.originalColor);
        this.material.emissive.setHex(this.originalColor);
        this.glbMaterials.forEach((entry) => {
          entry.mat.color?.setHex(entry.origColor);
          if (entry.mat.emissive) {
            entry.mat.emissive.setHex(entry.origEmissive);
            entry.mat.emissiveIntensity = 0;
          }
        });
      }
    }

    // Knockback decay
    if (this.knockbackVec.lengthSq() > 0.01) {
      this.group.position.addScaledVector(this.knockbackVec, delta);
      this.knockbackVec.multiplyScalar(Math.max(0, 1 - delta * 10));
    }

    // AI Move towards hero
    const dx = heroX - this.group.position.x;
    const dz = heroZ - this.group.position.z;
    const dist = Math.hypot(dx, dz);

    if (dist > 0.5 && dist < 14) {
      const vx = (dx / dist) * this.config.speed;
      const vz = (dz / dist) * this.config.speed;

      this.group.position.x += vx * delta;
      this.group.position.z += vz * delta;

      // Face move direction
      this.group.rotation.y = Math.atan2(dx, dz);

      // Bouncy jump animation on visualHolder
      this.jumpTimer += delta * (this.config.speed * 2.5);
      const jumpProgress = Math.abs(Math.sin(this.jumpTimer));
      this.visualHolder.position.y = jumpProgress * 0.32;
      const squash = 1 + jumpProgress * 0.16;
      const stretch = 1 / Math.sqrt(squash);
      this.visualHolder.scale.set(stretch, squash, stretch);
    } else {
      this.visualHolder.position.y = 0;
      this.visualHolder.scale.set(1, 1, 1);
    }
  }

  public takeDamage(
    damage: number,
    knockbackDirX: number,
    knockbackDirZ: number
  ): { dead: boolean; actualDamage: number } {
    if (this.isDead) return { dead: true, actualDamage: 0 };

    const actualDamage = Math.max(1, Math.round(damage));
    this.config.hp -= actualDamage;

    // Flash pure white on hit
    this.flashTimer = 0.14;
    this.material.color.setHex(0xffffff);
    this.material.emissive.setHex(0xffffff);
    this.glbMaterials.forEach((entry) => {
      if (entry.mat.emissive) {
        entry.mat.emissive.setHex(0xffffff);
        entry.mat.emissiveIntensity = 0.65;
      }
    });

    // Knockback
    const kbForce = this.config.type === 'GOLEM_BOSS' ? 2 : 6;
    this.knockbackVec.set(knockbackDirX * kbForce, 0, knockbackDirZ * kbForce);

    // Update HP bar fill
    const healthRatio = Math.max(0, this.config.hp / this.config.maxHp);
    this.hpBarFill.scale.x = healthRatio;

    if (this.config.hp <= 0) {
      this.isDead = true;
      this.group.visible = false;
      return { dead: true, actualDamage };
    }

    return { dead: false, actualDamage };
  }

  public getPosition(): THREE.Vector3 {
    return this.group.position;
  }

  public destroy(): void {
    this.group.traverse((obj) => {
      if (obj instanceof THREE.Mesh) {
        obj.geometry?.dispose();
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material?.dispose();
        }
      }
    });
    this.glbMaterials = [];
  }
}
