import { ISkillCard, SkillCardContext } from '../ISkillCard.ts';

export class LiquidityInjectionCard implements ISkillCard {
  public readonly id = 'LIQUIDITY_INJECTION';
  public readonly title = '流動性買盤注入';
  public readonly badge = '多頭掛單';
  public readonly category = 'WEAPON';
  public readonly iconKey = 'coinsPile';
  public readonly maxLevel = 10;
  public readonly financeTerm = '【流動性 (Liquidity)】市場買賣盤深度。大量買盤注入能抵抗拋售，推升幣價上攻。';

  public getDescription(currentLevel: number): string {
    const next = currentLevel + 1;
    if (next <= 4) return `掛出多重買盤！彈幕發射數量提升至 ${next + 1} 發`;
    if (next === 5) return '訂單撮合加速！攻擊冷卻縮短 25%';
    if (next <= 8) return `買盤深度擴大！彈幕發射數量提升至 ${next} 發`;
    if (next === 9) return '突破阻力位！彈幕發射數量達 9 發，獲得穿透效果 +1';
    return '多頭海嘯爆發！十發連環齊射，彈幕傷害提升 +30%，穿透效果 +1';
  }

  public isEligible(context: SkillCardContext): boolean {
    const current = context.engine.skillLevels?.get(this.id) ?? 0;
    return current < this.maxLevel;
  }

  public apply(context: SkillCardContext, nextLevel: number): void {
    const venom = context.weaponManager?.venom;
    if (venom) {
      if (typeof venom.upgrade === 'function') venom.upgrade();
      if (nextLevel <= 4) {
        venom.count = Math.min(10, nextLevel + 1);
      } else if (nextLevel === 5) {
        venom.cooldown = Math.max(160, (venom.cooldown || 420) - 50);
      } else if (nextLevel <= 8) {
        venom.count = Math.min(10, nextLevel);
      } else if (nextLevel === 9) {
        venom.count = 9;
        venom.pierce = (venom.pierce || 0) + 1;
      } else if (nextLevel >= 10) {
        venom.count = 10;
        venom.pierce = (venom.pierce || 0) + 1;
        venom.damage = Math.round((venom.damage || 22) * 1.3);
      }
    }
    context.engine.damageMultiplier = (context.engine.damageMultiplier || 1.0) * 1.05;
  }
}
