import * as THREE from 'three';
import { MobileLifecycleGovernor } from '../../../sdk/snek-pet/index.ts';

export interface StageOptions {
  container: HTMLElement;
  onUpdate?: (delta: number) => void;
}

export class Dungeon3DStage {
  public scene: THREE.Scene;
  public camera: THREE.PerspectiveCamera;
  public renderer: THREE.WebGLRenderer;
  public governor: MobileLifecycleGovernor;
  private container: HTMLElement;
  private onUpdateCallback?: (delta: number) => void;
  private resizeHandler: () => void;

  // Camera damping target
  private cameraTarget: THREE.Vector3 = new THREE.Vector3(0, 0, 0);
  private cameraOffset: THREE.Vector3 = new THREE.Vector3(0, 16, 13);

  // Dynamic hero light
  public heroLight: THREE.PointLight;

  constructor(options: StageOptions) {
    this.container = options.container;
    this.onUpdateCallback = options.onUpdate;

    // 1. Scene
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x0a0e17);
    this.scene.fog = new THREE.FogExp2(0x0a0e17, 0.035);

    // 2. Camera: Isometric 3D angle (FOV 45)
    const aspect = this.container.clientWidth / (this.container.clientHeight || 1);
    this.camera = new THREE.PerspectiveCamera(45, aspect, 0.1, 100);
    this.camera.position.copy(this.cameraOffset);
    this.camera.lookAt(0, 0, 0);

    // 3. WebGL Renderer with Spec 09 DPR <= 2.0 cap (with headless test fallback)
    try {
      this.renderer = new THREE.WebGLRenderer({
        antialias: true,
        powerPreference: 'high-performance',
      });
      this.renderer.setSize(this.container.clientWidth, this.container.clientHeight);
      this.renderer.setPixelRatio(MobileLifecycleGovernor.getClampedDpr());
      this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
      this.renderer.toneMappingExposure = 1.1;
    } catch {
      const fallbackCanvas = document.createElement('canvas');
      this.renderer = {
        domElement: fallbackCanvas,
        setSize: () => {},
        setPixelRatio: () => {},
        render: () => {},
        dispose: () => {},
        toneMapping: THREE.ACESFilmicToneMapping,
        toneMappingExposure: 1.1,
      } as unknown as THREE.WebGLRenderer;
    }

    // Canvas styling
    this.renderer.domElement.style.width = '100%';
    this.renderer.domElement.style.height = '100%';
    this.renderer.domElement.style.display = 'block';
    this.container.appendChild(this.renderer.domElement);

    // 4. Lights
    const ambientLight = new THREE.AmbientLight(0x2d3748, 1.4);
    this.scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffeedd, 2.0);
    dirLight.position.set(12, 22, 14);
    this.scene.add(dirLight);

    // Hero Torch / Aura PointLight
    this.heroLight = new THREE.PointLight(0x00e676, 3.5, 12, 1.2);
    this.heroLight.position.set(0, 2, 0);
    this.scene.add(this.heroLight);

    // 5. Handle Resize
    this.resizeHandler = () => this.handleResize();
    window.addEventListener('resize', this.resizeHandler);

    // 6. Start Loop governed by MobileLifecycleGovernor (60 FPS throttle + visibility sleep)
    this.governor = new MobileLifecycleGovernor({
      onUpdate: (deltaSec) => {
        if (this.onUpdateCallback) {
          this.onUpdateCallback(deltaSec);
        }
      },
      onRender: () => {
        this.renderer.render(this.scene, this.camera);
      },
    });
    this.governor.start();
  }

  public follow(x: number, z: number, dt: number): void {
    const lerpFactor = Math.min(1.0, dt * 6);
    this.cameraTarget.x += (x - this.cameraTarget.x) * lerpFactor;
    this.cameraTarget.z += (z - this.cameraTarget.z) * lerpFactor;

    this.camera.position.x = this.cameraTarget.x + this.cameraOffset.x;
    this.camera.position.y = this.cameraOffset.y;
    this.camera.position.z = this.cameraTarget.z + this.cameraOffset.z;

    this.camera.lookAt(this.cameraTarget.x, 0.5, this.cameraTarget.z);

    // Move hero light along
    this.heroLight.position.set(x, 2, z);
  }

  private handleResize(): void {
    if (!this.container || !this.renderer || !this.camera) return;
    const width = this.container.clientWidth;
    const height = this.container.clientHeight;
    if (width === 0 || height === 0) return;

    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.renderer.setPixelRatio(MobileLifecycleGovernor.getClampedDpr());
    this.renderer.setSize(width, height);
  }

  public destroy(): void {
    this.governor.stop();
    window.removeEventListener('resize', this.resizeHandler);

    if (this.renderer.domElement.parentElement) {
      this.renderer.domElement.parentElement.removeChild(this.renderer.domElement);
    }

    this.renderer.dispose();
  }
}
