export class FoodDrop3D {
  public group: THREE.Group;
  public config: FoodDropConfig;
  public isCollected: boolean = false;

  private visualHolder: THREE.Group;
  private ringMesh: THREE.Mesh;
  private fallbackMesh: THREE.Mesh;
  private animTime: number = Math.random() * Math.PI * 2;
  private spawnBounce: number = 0;

  constructor(scene: THREE.Scene, config: FoodDropConfig, posX: number, posZ: number) {
    this.config = { ...config };
    this.group = new THREE.Group();
    this.group.position.set(posX, 0, posZ);
    scene.add(this.group);

    // 1. Ground Glow Aura Ring
    const ringGeo = new THREE.RingGeometry(0.32, 0.52, 24);
    const ringMat = new THREE.MeshBasicMaterial({
      color: config.glowColor,
      transparent: true,
      opacity: 0.65,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    this.ringMesh = new THREE.Mesh(ringGeo, ringMat);
    this.ringMesh.rotation.x = -Math.PI / 2;
    this.ringMesh.position.y = 0.03;
    this.group.add(this.ringMesh);

    // 2. Floating Holder for 3D Food Model
    this.visualHolder = new THREE.Group();
    this.visualHolder.position.y = 0.45;
    this.group.add(this.visualHolder);

    // Lightweight fallback orb until GLB loads
    const fbGeo = new THREE.SphereGeometry(0.24, 10, 10);
    const fbMat = new THREE.MeshStandardMaterial({
      color: config.glowColor,
      roughness: 0.3,
      metalness: 0.2,
      emissive: config.glowColor,
      emissiveIntensity: 0.35,
    });
    this.fallbackMesh = new THREE.Mesh(fbGeo, fbMat);
    this.visualHolder.add(this.fallbackMesh);

    // Load Kenney 3D Food GLB
    this.loadModel(config.modelUrl);
  }

  private loadModel(url: string): void {
    GLTFModelLoader.getInstance()
      .load(url)
      .then((gltf) => {
        if (this.isCollected) return;
        const { scene: model } = GLTFModelLoader.getInstance().instantiate(gltf);

        // Normalize size so food drop is clearly visible (~0.75 units wide)
        const box = new THREE.Box3().setFromObject(model);
        const size = new THREE.Vector3();
        const center = new THREE.Vector3();
        box.getSize(size);
        box.getCenter(center);

        const maxDim = Math.max(size.x, size.y, size.z, 0.01);
        const targetSize = this.config.effectType === 'WEAPON_UPGRADE' ? 0.95 : 0.72;
        const scale = targetSize / maxDim;
        model.scale.setScalar(scale);
        model.position.set(-center.x * scale, -box.min.y * scale, -center.z * scale);

        this.fallbackMesh.visible = false;
        this.visualHolder.add(model);
      })
      .catch(() => {
        // Keep fallback sphere in headless/test environment
      });
  }

  public update(delta: number, heroX: number, heroZ: number): boolean {
    if (this.isCollected) return false;

    this.animTime += delta * 3.5;
    this.spawnBounce = Math.min(1.0, this.spawnBounce + delta * 4.0);

    // Gentle hover and spin
    this.visualHolder.position.y = 0.32 + Math.sin(this.animTime) * 0.12;
    this.visualHolder.rotation.y += delta * 2.2;

    const pulse = 0.88 + Math.sin(this.animTime * 1.5) * 0.12;
    this.ringMesh.scale.setScalar(pulse);

    // Check pickup distance with hero
    const dx = heroX - this.group.position.x;
    const dz = heroZ - this.group.position.z;
    if (Math.hypot(dx, dz) < 1.25) {
      this.isCollected = true;
      this.group.visible = false;
      return true;
    }

    return false;
  }

  public destroy(): void {
    this.group.traverse((obj) => {
      if (obj instanceof THREE.Mesh) {
        obj.geometry?.dispose();
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material?.dispose();
        }
      }
    });
  }
}
