import { IBalanceRule } from '../IBalanceRule.ts';
import { PacingMetrics, PacingModifiers, PacingState } from '../types.ts';

/**
 * SlogAssistRule (清怪破荒規則)
 * When a player has not leveled up for > 35 seconds in general mob waves (usually stage 3+ / 30+ levels),
 * adaptively accelerates mob EXP drops and clears pacing friction so the player levels up cleanly.
 */
export class SlogAssistRule implements IBalanceRule {
  public readonly id = 'SLOG_ASSIST_RULE';

  public evaluate(
    metrics: PacingMetrics,
    modifiers: PacingModifiers,
    currentState: PacingState
  ): PacingState | void {
    // Only applies outside of active boss combat
    if (metrics.bossCombatTime <= 0 && metrics.timeSinceLevelUp > 35) {
      modifiers.expDropMultiplier = Math.max(modifiers.expDropMultiplier, 2.5);
      modifiers.magnetRadiusMultiplier = Math.max(modifiers.magnetRadiusMultiplier, 1.25);
      modifiers.playerAttackSpeedMultiplier = Math.max(modifiers.playerAttackSpeedMultiplier, 1.15);
      return 'SLOG_ASSIST';
    }
    return currentState;
  }
}
