export interface MonsterSpawnSpec {
  config: MonsterConfig;
  x: number;
  z: number;
}

/**
 * 依據樓層產生該層怪物與首領的生成配置陣列（純函式，方便 BDD 測試）
 */
export function buildFloorMonsterSpawns(floor: number): MonsterSpawnSpec[] {
  const isBossFloor = floor % 5 === 0;
  const spawns: MonsterSpawnSpec[] = [];

  if (isBossFloor) {
    const bossEntry = BOSS_ROSTER[Math.floor(floor / 5 - 1) % BOSS_ROSTER.length];
    const bossHp = 250 + floor * 50;
    spawns.push({
      config: {
        id: `boss_${floor}`,
        type: 'GOLEM_BOSS',
        name: `${bossEntry.name} Lv.${floor}`,
        maxHp: bossHp,
        hp: bossHp,
        atk: 25 + floor * 3,
        speed: 2.2,
        size: 1.25,
        color: bossEntry.color,
        expValue: 100,
        modelUrl: bossEntry.modelUrl,
      },
      x: 0,
      z: -4,
    });

    for (let i = 0; i < 2; i++) {
      const sideX = i === 0 ? -4.5 : 4.5;
      const escortEntry = CUBE_PET_MONSTERS[(floor + i * 3) % CUBE_PET_MONSTERS.length];
      spawns.push({
        config: {
          id: `escort_${i}`,
          type: 'SLIME',
          name: `護衛${escortEntry.name}`,
          maxHp: 60 + floor * 10,
          hp: 60 + floor * 10,
          atk: 12 + floor * 2,
          speed: 3.2,
          size: 0.65,
          color: escortEntry.color,
          expValue: 30,
          modelUrl: escortEntry.modelUrl,
        },
        x: sideX,
        z: -2,
      });
    }
  } else {
    const count = Math.min(3 + floor, 8);
    const spawnZones = [
      { x: -4, z: -4 },
      { x: 4, z: -4 },
      { x: 0, z: -2 },
      { x: -5, z: 1 },
      { x: 5, z: 1 },
      { x: -3, z: -7 },
      { x: 3, z: -7 },
      { x: 0, z: -5 },
    ];

    for (let i = 0; i < count; i++) {
      const zone = spawnZones[i % spawnZones.length];
      const jitterX = (Math.random() - 0.5) * 1.5;
      const jitterZ = (Math.random() - 0.5) * 1.5;

      const petEntry = CUBE_PET_MONSTERS[(floor * 2 + i) % CUBE_PET_MONSTERS.length];
      const hp = 35 + floor * 8;
      spawns.push({
        config: {
          id: `slime_${floor}_${i}`,
          type: 'SLIME',
          name: petEntry.name,
          maxHp: hp,
          hp: hp,
          atk: 10 + floor * 2,
          speed: 2.8 + Math.random() * 0.8,
          size: 0.58 + Math.random() * 0.14,
          color: petEntry.color,
          expValue: 20,
          modelUrl: petEntry.modelUrl,
        },
        x: zone.x + jitterX,
        z: zone.z + jitterZ,
      });
    }
  }

  return spawns;
}
