import * as THREE from 'three';
import { Hero3D } from '../entities/Hero3D.ts';
import { Monster3D } from '../entities/Monster3D.ts';
import { Projectile3D } from '../entities/Projectile3D.ts';

export interface ProjectileHitEvent {
  monster: Monster3D;
  damage: number;
  actualDamage: number;
  vx: number;
  vz: number;
  isCrit: boolean;
  dead: boolean;
}

export class CollisionSystem {
  /**
   * 更新場上所有投射物並處理與怪物的碰撞、貫穿與範圍爆炸波及
   */
  public static resolveProjectiles(
    delta: number,
    scene: THREE.Scene,
    projectiles: Projectile3D[],
    monsters: Monster3D[],
    onHit: (event: ProjectileHitEvent) => void
  ): Projectile3D[] {
    const remaining: Projectile3D[] = [];

    for (let i = 0; i < projectiles.length; i++) {
      const proj = projectiles[i];
      proj.update(delta);

      if (proj.isExpired) {
        proj.destroy();
        scene.remove(proj.group);
        continue;
      }

      let shouldConsumeProjectile = false;
      const pPos = proj.getPosition();

      for (let j = 0; j < monsters.length; j++) {
        const monster = monsters[j];
        if (monster.isDead || proj.hitMonsterIds.has(monster.config.id)) continue;

        const mPos = monster.getPosition();
        const dist = Math.hypot(pPos.x - mPos.x, pPos.z - mPos.z);
        const hitRadius = monster.config.size * 0.75 + proj.radius;

        if (dist < hitRadius) {
          proj.hitMonsterIds.add(monster.config.id);

          const primaryRes = monster.takeDamage(
            proj.config.damage,
            proj.config.vx,
            proj.config.vz
          );
          onHit({
            monster,
            damage: proj.config.damage,
            actualDamage: primaryRes.actualDamage,
            vx: proj.config.vx,
            vz: proj.config.vz,
            isCrit: proj.config.isCrit,
            dead: primaryRes.dead,
          });

          // AoE Splash Damage if explosionRadius > 0
          if (proj.explosionRadius > 0) {
            const splashDmg = Math.max(1, Math.round(proj.config.damage * 0.6));
            for (let k = 0; k < monsters.length; k++) {
              const other = monsters[k];
              if (other.isDead || other.config.id === monster.config.id) continue;
              const oPos = other.getPosition();
              if (Math.hypot(oPos.x - mPos.x, oPos.z - mPos.z) <= proj.explosionRadius) {
                const splashRes = other.takeDamage(
                  splashDmg,
                  proj.config.vx,
                  proj.config.vz
                );
                onHit({
                  monster: other,
                  damage: splashDmg,
                  actualDamage: splashRes.actualDamage,
                  vx: proj.config.vx,
                  vz: proj.config.vz,
                  isCrit: false,
                  dead: splashRes.dead,
                });
              }
            }
          }

          if (proj.pierceLeft > 0) {
            proj.pierceLeft--;
          } else {
            shouldConsumeProjectile = true;
            break;
          }
        }
      }

      if (shouldConsumeProjectile) {
        proj.destroy();
        scene.remove(proj.group);
      } else {
        remaining.push(proj);
      }
    }

    return remaining;
  }

  /**
   * 更新怪物追擊並檢查與主角的接觸傷害
   */
  public static resolveMonstersAndContact(
    delta: number,
    hero: Hero3D,
    monsters: Monster3D[],
    camera: THREE.Camera,
    onHeroDamaged: (rawAtk: number, heroDied: boolean) => void
  ): void {
    const heroPos = hero.getPosition();
    for (let i = 0; i < monsters.length; i++) {
      const monster = monsters[i];
      if (monster.isDead) continue;

      monster.update(delta, heroPos.x, heroPos.z, camera);

      const mPos = monster.getPosition();
      const dist = Math.hypot(mPos.x - heroPos.x, mPos.z - heroPos.z);
      const contactDist = 0.55 + monster.config.size * 0.6;

      if (dist < contactDist) {
        const damaged = hero.takeDamage(monster.config.atk);
        if (damaged) {
          const heroDied = !hero.isAlive();
          onHeroDamaged(monster.config.atk, heroDied);
          if (heroDied) return;
        }
      }
    }
  }
}
