import { SurvivorEngine } from '../SurvivorEngine.ts';
import { BossDefeatSnapshot } from '../save/types.ts';
import { SaveManager } from '../save/SaveManager.ts';
import { I18nService } from '../../../platform/I18nService.ts';

export class SurvivorLifecycleManager {
  public static revive(engine: SurvivorEngine): boolean {
    engine.hp = engine.maxHp;
    engine.invulnerableTimer = 4000;
    engine.canRevive = false;
    engine.pvx = 0;
    engine.pvy = 0;

    // Nuke / Clear non-boss enemies around player
    let deadCount = 0;
    for (const e of engine.enemies) {
      if (!e.isBoss) {
        deadCount++;
        engine.particleSystem.emitDeath(e.x, e.y);
        engine.lootManager.addGem(e.x, e.y, 2, 'NORMAL');
      }
    }
    engine.enemies = engine.enemies.filter((e) => e.isBoss);
    engine.kills += deadCount;
    engine.callbacks.onKillsChange(engine.kills);

    // Repel active boss away to arena top and reset active action/hazard states
    if (engine.currentBoss) {
      const b = engine.currentBoss;
      b.y = 80;
      b.state = 'FORMATION_HOVER';
      b.stateTimer = 0;
      b.shockwaves = [];
      b.bombs = [];
      b.telegraphs = [];
      b.dashVx = 0;
      b.dashVy = 0;
      b.bounceVx = 0;
      b.bounceVy = 0;
      b.bounceCount = 0;
      b.isDeflectingProjectiles = false;
      b.gravityPullActive = false;
      if (b.laser) b.laser.active = false;
    }

    engine.callbacks.onHpChange(engine.hp, engine.maxHp);
    engine.soundManager.playHighScore();
    const isEn = I18nService.getInstance().getLocale() === 'en';
    engine.addFloatingText(isEn ? 'REVIVED (FULL HP)' : '滿血復活重生', '#ffd700');

    for (let i = 0; i < 24; i++) {
      engine.particleSystem.emitSuperEat(engine.px, engine.py);
    }

    // Clear active boss projectiles and hazardous strikes so player is safe upon reviving
    if (engine.bossCombatController) {
      engine.bossCombatController.bossBullets = [];
      engine.bossCombatController.hazardZones = [];
      engine.bossCombatController.barricades = [];
      engine.bossCombatController.crossLaser = null;
      engine.bossCombatController.wickStrike = null;
    }

    // Cancel existing RAF frame and restart game loop cleanly
    if ((engine as any).animFrameId !== null) {
      cancelAnimationFrame((engine as any).animFrameId);
      (engine as any).animFrameId = null;
    }
    engine.isRunning = false;
    engine.isPaused = false;
    engine.start();
    return true;
  }

  public static restartGame(engine: SurvivorEngine): void {
    SaveManager.getInstance().clearLevelCheckpoint();
    engine.isRunning = false;
    engine.isPaused = false;
    engine.stage = 1;
    engine.level = 1;
    engine.exp = 0;
    engine.nextExp = 10;
    engine.hp = 100;
    engine.maxHp = 100;
    engine.kills = 0;
    engine.elapsedTime = 0;
    engine.comboMeter = 0;
    engine.isFever = false;
    engine.feverTimer = 0;
    engine.enemies = [];
    engine.projectiles = [];
    engine.pickups = [];
    engine.currentBoss = null;
    engine.bossCombatController.resetBoss();
    engine.invulnerableTimer = 1000;
    engine.canRevive = true;
    engine.px = engine.width / 2;
    engine.py = engine.height / 2;
    engine.pvx = 0;
    engine.pvy = 0;
    engine.callbacks.onHpChange(engine.hp, engine.maxHp);
    engine.callbacks.onExpChange(engine.exp, engine.nextExp, engine.level);
    engine.callbacks.onKillsChange(engine.kills);
    engine.callbacks.onTimerChange(0);
    engine.callbacks.onStageChange?.(1, '關卡 1');
    engine.start();
  }

  public static loadSnapshotAndStart(engine: SurvivorEngine, snapshot: BossDefeatSnapshot): void {
    engine.isRunning = false;
    engine.isPaused = false;
    engine.stage = snapshot.stage;
    engine.level = snapshot.playerStats.level;
    engine.nextExp = engine.getNextExpForLevel(engine.level);
    engine.exp = 0;
    engine.hp = snapshot.playerStats.hp;
    engine.maxHp = snapshot.playerStats.maxHp;
    engine.speed = snapshot.playerStats.speed;
    engine.playerSize = snapshot.playerStats.playerSize;
    engine.damageReduction = snapshot.playerStats.damageReduction;
    engine.damageMultiplier = snapshot.playerStats.damageMultiplier;
    engine.magnetRadius = snapshot.playerStats.magnetRadius;
    engine.hasCompoundInterest = snapshot.playerStats.hasCompoundInterest;

    engine.venomCount = snapshot.playerStats.weapons.venomCount;
    engine.venomCooldown = snapshot.playerStats.weapons.venomCooldown;
    engine.orbitCount = snapshot.playerStats.weapons.orbitCount;
    engine.orbitSpeed = snapshot.playerStats.weapons.orbitSpeed;

    engine.kills = snapshot.kills;
    engine.elapsedTime = snapshot.elapsedTime;
    engine.comboMeter = 0;
    engine.isFever = false;
    engine.feverTimer = 0;

    // Restore skill levels or backward-reconstruct for legacy snapshots
    if (snapshot.playerStats.skillLevels && Object.keys(snapshot.playerStats.skillLevels).length > 0) {
      engine.skillLevels = new Map(Object.entries(snapshot.playerStats.skillLevels));
    } else {
      engine.skillLevels = new Map<string, number>();
      if (engine.venomCount > 1) {
        engine.skillLevels.set('LIQUIDITY_INJECTION', Math.min(10, engine.venomCount));
      }
      if (engine.orbitCount > 0) {
        engine.skillLevels.set('HEDGE_OPTIONS_SHIELD', Math.min(10, engine.orbitCount * 2));
      }
      if (engine.hasCompoundInterest) {
        engine.skillLevels.set('COMPOUND_INTEREST', 1);
      }
      if (engine.maxHp > 100) {
        const hpTier = Math.min(8, Math.floor((engine.maxHp - 100) / 30));
        if (hpTier > 0) engine.skillLevels.set('DIAMOND_HANDS', hpTier);
      }
      if (engine.magnetRadius > 65) {
        engine.skillLevels.set('WHALE_MAGNET', 1);
      }
    }

    engine.enemies = [];
    engine.projectiles = [];
    engine.pickups = [];
    engine.currentBoss = null;
    engine.bossCombatController.resetBoss();
    engine.invulnerableTimer = 1500;
    engine.canRevive = true;
    engine.px = engine.width / 2;
    engine.py = engine.height / 2;
    engine.pvx = 0;
    engine.pvy = 0;

    engine.callbacks.onHpChange(engine.hp, engine.maxHp);
    engine.callbacks.onExpChange(engine.exp, engine.nextExp, engine.level);
    engine.callbacks.onKillsChange(engine.kills);
    engine.callbacks.onTimerChange(Math.floor(engine.elapsedTime));
    engine.callbacks.onStageChange?.(engine.stage, snapshot.bossTitle || `Stage ${engine.stage}`);

    engine.triggerBossEncounter(snapshot.stage);
    engine.start();
  }

  public static spawnWhaleBoss(engine: SurvivorEngine): void {
    if (engine.enemies.some((e) => e.type === 'WHALE_BOSS')) return;
    engine.enemies.push({
      id: `boss_whale_${Date.now()}`,
      x: engine.width / 2,
      y: -50,
      hp: 360,
      maxHp: 360,
      speed: 0.65,
      size: 32,
      type: 'WHALE_BOSS',
      color: '#00b0ff',
      isBoss: true,
      rotation: 0,
    });
  }

  public static handleGameClear(engine: SurvivorEngine): void {
    SaveManager.getInstance().clearLevelCheckpoint();
    engine.isRunning = false;
    engine.pause();
    engine.soundManager.playHighScore();
    for (let i = 0; i < 36; i++) {
      engine.particleSystem.emitEat(
        engine.width / 2 + (Math.random() - 0.5) * 260,
        engine.height / 3 + (Math.random() - 0.5) * 180
      );
    }
    engine.callbacks.onGameClear?.(engine.kills, Math.floor(engine.elapsedTime), engine.level);
  }

  public static handleGameOver(engine: SurvivorEngine): void {
    if ((engine as any).animFrameId !== null) {
      cancelAnimationFrame((engine as any).animFrameId);
      (engine as any).animFrameId = null;
    }
    engine.isRunning = false;
    engine.soundManager.playDie();
    engine.particleSystem.emitDeath(engine.px, engine.py);
    engine.callbacks.onGameOver(engine.kills, Math.floor(engine.elapsedTime), engine.level);
  }

  public static restartFromCheckpoint(engine: SurvivorEngine, saveMgr?: SaveManager): boolean {
    const sm = saveMgr ?? SaveManager.getInstance();
    const checkpoint = sm.getLevelCheckpoint();
    if (!checkpoint) return false;

    engine.level = checkpoint.level;
    engine.stage = checkpoint.stage;
    engine.maxHp = checkpoint.maxHp;
    engine.hp = checkpoint.maxHp;
    engine.speed = checkpoint.speed;
    engine.damageReduction = checkpoint.damageReduction;
    engine.damageMultiplier = checkpoint.damageMultiplier;
    engine.magnetRadius = checkpoint.magnetRadius;
    engine.hasCompoundInterest = checkpoint.hasCompoundInterest;
    engine.kills = checkpoint.kills;
    engine.elapsedTime = checkpoint.elapsedTime;

    // Restore skill levels or backward-reconstruct for legacy checkpoints
    if (checkpoint.skillLevels && Object.keys(checkpoint.skillLevels).length > 0) {
      engine.skillLevels = new Map(Object.entries(checkpoint.skillLevels));
    } else {
      engine.skillLevels = new Map<string, number>();
      if (checkpoint.weapons?.venomCount > 1) {
        engine.skillLevels.set('LIQUIDITY_INJECTION', Math.min(10, checkpoint.weapons.venomCount));
      }
      if (checkpoint.weapons?.orbitCount > 0) {
        engine.skillLevels.set('HEDGE_OPTIONS_SHIELD', Math.min(10, checkpoint.weapons.orbitCount * 2));
      }
      if (checkpoint.hasCompoundInterest) {
        engine.skillLevels.set('COMPOUND_INTEREST', 1);
      }
      if (checkpoint.maxHp > 100) {
        const hpTier = Math.min(8, Math.floor((checkpoint.maxHp - 100) / 30));
        if (hpTier > 0) engine.skillLevels.set('DIAMOND_HANDS', hpTier);
      }
      if (checkpoint.magnetRadius > 65) {
        engine.skillLevels.set('WHALE_MAGNET', 1);
      }
      if (checkpoint.speed > 2.4) {
        const speedTier = Math.min(8, Math.round((checkpoint.speed - 2.4) / 0.1));
        if (speedTier > 0) engine.skillLevels.set('ARBITRAGE_SPRINT', speedTier);
      }
    }

    if (engine.weaponManager) {
      engine.weaponManager.venom.count = checkpoint.weapons.venomCount;
      engine.weaponManager.venom.cooldown = checkpoint.weapons.venomCooldown;
      engine.weaponManager.orbiter.count = checkpoint.weapons.orbitCount;
      engine.weaponManager.orbiter.speed = checkpoint.weapons.orbitSpeed;
    }

    engine.exp = 0;
    engine.nextExp = typeof engine.getNextExpForLevel === 'function' ? engine.getNextExpForLevel(engine.level) : 100;

    engine.px = engine.width / 2;
    engine.py = engine.height / 2;
    engine.pvx = 0;
    engine.pvy = 0;

    engine.invulnerableTimer = 3000;
    engine.canRevive = true;

    engine.enemies = [];
    engine.currentBoss = null;
    if (engine.bossCombatController) {
      engine.bossCombatController.resetBoss();
      engine.bossCombatController.bossBullets = [];
      engine.bossCombatController.hazardZones = [];
    }

    engine.callbacks.onHpChange(engine.hp, engine.maxHp);
    engine.callbacks.onExpChange(engine.exp, engine.nextExp, engine.level);
    engine.callbacks.onKillsChange(engine.kills);
    engine.callbacks.onTimerChange(engine.elapsedTime);
    engine.callbacks.onStageChange?.(engine.stage, `STAGE ${engine.stage}`);

    const isEn = I18nService.getInstance().getLocale() === 'en';
    engine.addFloatingText(isEn ? `RESTART AT LV.${engine.level}` : `從 LV.${engine.level} 重新出發`, '#00e676');

    if ((engine as any).animFrameId !== null) {
      cancelAnimationFrame((engine as any).animFrameId);
      (engine as any).animFrameId = null;
    }
    engine.isRunning = false;
    engine.isPaused = false;
    engine.start();
    return true;
  }
}
