import { ISkillCard, SkillCardContext } from './ISkillCard.ts';
import { LiquidityInjectionCard } from './cards/LiquidityInjectionCard.ts';
import { HedgeOptionsShieldCard } from './cards/HedgeOptionsShieldCard.ts';
import { FlashLoanPulseCard } from './cards/FlashLoanPulseCard.ts';
import { DiamondHandsCard } from './cards/DiamondHandsCard.ts';
import { StakingYieldCard } from './cards/StakingYieldCard.ts';
import { HardwareEnclaveCard } from './cards/HardwareEnclaveCard.ts';
import { LeverageLongCard } from './cards/LeverageLongCard.ts';
import { CompoundInterestCard } from './cards/CompoundInterestCard.ts';
import { CooldownQuantCard } from './cards/CooldownQuantCard.ts';
import { GasFuelBoostCard } from './cards/GasFuelBoostCard.ts';
import { ArbitrageSprintCard } from './cards/ArbitrageSprintCard.ts';
import { WhaleMagnetCard } from './cards/WhaleMagnetCard.ts';
import { BullMarketFeverCard } from './cards/BullMarketFeverCard.ts';
import { MarketMakerLuckCard } from './cards/MarketMakerLuckCard.ts';
import { TalentDef } from '../data/talents.ts';
import { SaveManager } from '../save/SaveManager.ts';

export class SkillCardRegistry {
  private static instance: SkillCardRegistry | null = null;
  private cards: Map<string, ISkillCard> = new Map();

  constructor() {
    this.registerDefaults();
  }

  public static getInstance(): SkillCardRegistry {
    if (!SkillCardRegistry.instance) {
      SkillCardRegistry.instance = new SkillCardRegistry();
    }
    return SkillCardRegistry.instance;
  }

  private registerDefaults(): void {
    const defaultCards: ISkillCard[] = [
      new LiquidityInjectionCard(),
      new HedgeOptionsShieldCard(),
      new FlashLoanPulseCard(),
      new DiamondHandsCard(),
      new StakingYieldCard(),
      new HardwareEnclaveCard(),
      new LeverageLongCard(),
      new CompoundInterestCard(),
      new CooldownQuantCard(),
      new GasFuelBoostCard(),
      new ArbitrageSprintCard(),
      new WhaleMagnetCard(),
      new BullMarketFeverCard(),
      new MarketMakerLuckCard(),
    ];

    for (const card of defaultCards) {
      this.registerCard(card);
    }
  }

  public registerCard(card: ISkillCard): void {
    this.cards.set(card.id, card);
  }

  public getCard(id: string): ISkillCard | undefined {
    return this.cards.get(id);
  }

  public getAllCards(): ISkillCard[] {
    return Array.from(this.cards.values());
  }

  public getEligibleCards(context: SkillCardContext): ISkillCard[] {
    return this.getAllCards().filter((card) => card.isEligible(context));
  }

  public drawCards(context: SkillCardContext, count: number = 3): ISkillCard[] {
    const eligible = this.getEligibleCards(context);
    if (eligible.length <= count) {
      return [...eligible];
    }
    const shuffled = [...eligible].sort(() => Math.random() - 0.5);
    return shuffled.slice(0, count);
  }

  public drawTalentDefs(engine: any, count: number = 3): TalentDef[] {
    const context = this.createContext(engine);
    const drawn = this.drawCards(context, count);

    return drawn.map((card) => {
      const currentLevel = engine.skillLevels?.get(card.id) ?? 0;
      return {
        id: card.id,
        title: card.title,
        badge: card.badge,
        desc: card.getDescription(currentLevel),
        financeTerm: card.financeTerm || '',
        category: (card.category === 'WEAPON' ? 'WEAPON' : card.category === 'SPECIAL' ? 'SPECIAL' : 'STATS') as any,
        iconKey: card.iconKey,
        currentLevel,
        maxLevel: card.maxLevel,
      };
    });
  }

  public applyCard(contextOrEngine: any, cardId: string): void {
    const isEngine = typeof contextOrEngine.applyUpgrade === 'function' || contextOrEngine.weaponManager !== undefined;
    const engine = isEngine && contextOrEngine.engine ? contextOrEngine.engine : contextOrEngine;
    const context = this.createContext(engine);

    const card = this.getCard(cardId);
    if (!card) return;

    if (!engine.skillLevels) {
      engine.skillLevels = new Map<string, number>();
    }

    const currentLevel = engine.skillLevels.get(cardId) ?? 0;
    if (currentLevel >= card.maxLevel) return;

    const nextLevel = currentLevel + 1;
    card.apply(context, nextLevel);
    engine.skillLevels.set(cardId, nextLevel);

    // Save checkpoint if SaveManager is available
    try {
      SaveManager.getInstance().saveLevelCheckpoint({
        level: engine.level,
        stage: engine.stage ?? 1,
        hp: engine.hp,
        maxHp: engine.maxHp,
        speed: engine.speed,
        damageReduction: engine.damageReduction,
        damageMultiplier: engine.damageMultiplier,
        magnetRadius: engine.magnetRadius,
        hasCompoundInterest: engine.hasCompoundInterest,
        weapons: {
          venomCount: engine.weaponManager?.venom?.count ?? 1,
          venomCooldown: engine.weaponManager?.venom?.cooldown ?? 420,
          orbitCount: engine.weaponManager?.orbiter?.count ?? 0,
          orbitSpeed: engine.weaponManager?.orbiter?.speed ?? 0,
        },
        kills: engine.kills ?? 0,
        elapsedTime: engine.elapsedTime ?? 0,
        skillLevels: engine.skillLevels ? Object.fromEntries(engine.skillLevels) : undefined,
      });
    } catch {
      // Resilience for test environment
    }
  }

  public getAcquiredCards(engine: any): Array<{ card: ISkillCard; level: number }> {
    const result: Array<{ card: ISkillCard; level: number }> = [];
    if (!engine.skillLevels) return result;

    for (const [id, level] of engine.skillLevels.entries()) {
      if (level > 0) {
        const card = this.getCard(id);
        if (card) {
          result.push({ card, level });
        }
      }
    }
    return result;
  }

  private createContext(engine: any): SkillCardContext {
    if (!engine.skillLevels) {
      engine.skillLevels = new Map<string, number>();
    }

    return {
      engine,
      level: engine.level ?? 1,
      currentLevel: engine.level ?? 1,
      hp: engine.hp ?? 100,
      maxHp: engine.maxHp ?? 100,
      speed: engine.speed ?? 2.4,
      damageMultiplier: engine.damageMultiplier ?? 1.0,
      damageReduction: engine.damageReduction ?? 0,
      magnetRadius: engine.magnetRadius ?? 65,
      hasCompoundInterest: !!engine.hasCompoundInterest,
      critChance: engine.critChance ?? 0,
      critMultiplier: engine.critMultiplier ?? 1.5,
      hpRegenRate: engine.hpRegenRate ?? 0,
      cooldownReduction: engine.cooldownReduction ?? 0,
      projectileSpeedBonus: engine.projectileSpeedBonus ?? 0,
      projectilePierceBonus: engine.projectilePierceBonus ?? 0,
      feverBonus: engine.feverBonus ?? 0,
      lootBonus: engine.lootBonus ?? 0,
      invulnerableBonus: engine.invulnerableBonus ?? 0,
      weaponManager: engine.weaponManager,
      soundManager: engine.soundManager,
      particleSystem: engine.particleSystem,
      callbacks: engine.callbacks,
    };
  }
}
