import {
  ALL_ENCHANTMENT_ORDER,
  CRAFTABLE_WEAPONS_CATALOG,
  CraftableWeaponRecipe,
  DEFAULT_BACKPACK_CAPACITY,
  ITEM_CATALOG,
  KITCHEN_RECIPES,
  MAX_ITEM_STACK_PER_SLOT,
  SnekItemEntry,
} from '../catalogs/itemsCatalog.ts';
import { SnekPetPassport, WeaponEnchantmentTag } from '../types.ts';
import { ArtisanForgeService, MAX_WEAPON_UPGRADE_LEVEL } from './ArtisanForgeService.ts';

export interface BackpackAddResult {
  passport: SnekPetPassport;
  addedItems: Record<string, number>;
  overflowItems: Record<string, number>;
  isFull: boolean;
}

export interface NineGridSlot {
  slotIndex: number;
  itemId: string | null;
  entry: SnekItemEntry | null;
  count: number;
}

export class SnekInventoryService {
  /**
   * 取得隨身九宮格背包空間上限 (預設 9 格)
   */
  public static getBackpackCapacity(passport: SnekPetPassport): number {
    return typeof passport.backpackCapacity === 'number' && passport.backpackCapacity > 0
      ? passport.backpackCapacity
      : DEFAULT_BACKPACK_CAPACITY;
  }

  /**
   * 計算隨身背包目前佔用的「格子數」(以 MAX_ITEM_STACK_PER_SLOT=99 為一格，最多佔 9 格)
   */
  public static getBackpackUsedCount(passport: SnekPetPassport): number {
    let usedSlots = 0;
    for (const count of Object.values(passport.inventory || {})) {
      if (typeof count === 'number' && count > 0) {
        usedSlots += Math.ceil(Math.floor(count) / MAX_ITEM_STACK_PER_SLOT);
      }
    }
    return usedSlots;
  }

  /**
   * 計算隨身背包剩餘可用格子數
   */
  public static getBackpackRemainingSpace(passport: SnekPetPassport): number {
    const cap = SnekInventoryService.getBackpackCapacity(passport);
    const used = SnekInventoryService.getBackpackUsedCount(passport);
    return Math.max(0, cap - used);
  }

  /**
   * 將隨身背包展開為固定 9 格 (3x3 九宮格卡片) 結構供 UI 渲染，同類道具堆疊於同一格
   */
  public static getNineGridSlots(passport: SnekPetPassport): NineGridSlot[] {
    const slots: NineGridSlot[] = [];
    const cap = SnekInventoryService.getBackpackCapacity(passport);

    for (const [itemId, rawCount] of Object.entries(passport.inventory || {})) {
      let remCount = Math.floor(rawCount || 0);
      if (remCount <= 0) continue;
      const entry = ITEM_CATALOG[itemId] || null;

      // 若超過 99 則切分成多格堆疊，每格最多 99
      while (remCount > 0 && slots.length < cap) {
        const stackCount = Math.min(MAX_ITEM_STACK_PER_SLOT, remCount);
        slots.push({
          slotIndex: slots.length,
          itemId,
          entry,
          count: stackCount,
        });
        remCount -= stackCount;
      }
    }

    while (slots.length < cap) {
      slots.push({
        slotIndex: slots.length,
        itemId: null,
        entry: null,
        count: 0,
      });
    }
    return slots;
  }

  /**
   * 將地下城戰利品裝入隨身背包（同類道具優先堆疊至 99，超出或新品項佔用空格，滿 9 格後回報溢出）
   */
  public static addItemsToBackpack(
    passport: SnekPetPassport,
    itemsToAdd: Record<string, number>
  ): BackpackAddResult {
    const cap = SnekInventoryService.getBackpackCapacity(passport);
    const nextInventory: Record<string, number> = { ...(passport.inventory || {}) };
    const addedItems: Record<string, number> = {};
    const overflowItems: Record<string, number> = {};

    for (const [itemId, rawCount] of Object.entries(itemsToAdd)) {
      let requested = Math.max(0, Math.floor(rawCount || 0));
      if (requested <= 0) continue;

      // 步驟 1：優先填滿現有未滿 99 的同類道具堆疊槽
      const curCount = nextInventory[itemId] || 0;
      const partialRem = curCount % MAX_ITEM_STACK_PER_SLOT;
      if (partialRem > 0) {
        const fillSpace = MAX_ITEM_STACK_PER_SLOT - partialRem;
        const fillCount = Math.min(fillSpace, requested);
        nextInventory[itemId] = curCount + fillCount;
        addedItems[itemId] = (addedItems[itemId] || 0) + fillCount;
        requested -= fillCount;
      }

      // 步驟 2：剩餘數量需佔用新的空格
      if (requested > 0) {
        // 計算當前已佔用的總格數
        let currentUsedSlots = 0;
        for (const cnt of Object.values(nextInventory)) {
          if (typeof cnt === 'number' && cnt > 0) {
            currentUsedSlots += Math.ceil(cnt / MAX_ITEM_STACK_PER_SLOT);
          }
        }
        const remainingEmptySlots = Math.max(0, cap - currentUsedSlots);
        const maxCanFitInEmptySlots = remainingEmptySlots * MAX_ITEM_STACK_PER_SLOT;
        const canFit = Math.min(requested, maxCanFitInEmptySlots);
        const overflow = requested - canFit;

        if (canFit > 0) {
          nextInventory[itemId] = (nextInventory[itemId] || 0) + canFit;
          addedItems[itemId] = (addedItems[itemId] || 0) + canFit;
        }
        if (overflow > 0) {
          overflowItems[itemId] = overflow;
        }
      }
    }

    const updated: SnekPetPassport = {
      ...passport,
      inventory: nextInventory,
    };

    return {
      passport: updated,
      addedItems,
      overflowItems,
      isFull: SnekInventoryService.getBackpackRemainingSpace(updated) === 0,
    };
  }

  /**
   * 中央客廳「無限儲物箱 (HOME_STASH)」：將隨身背包全部道具一鍵存入無限儲物箱
   */
  public static depositAllToStash(passport: SnekPetPassport): {
    passport: SnekPetPassport;
    depositedCount: number;
  } {
    const nextStash: Record<string, number> = { ...(passport.stash || {}) };
    let depositedCount = 0;

    for (const [itemId, count] of Object.entries(passport.inventory || {})) {
      const safe = Math.max(0, Math.floor(count || 0));
      if (safe > 0) {
        nextStash[itemId] = (nextStash[itemId] || 0) + safe;
        depositedCount += safe;
      }
    }

    return {
      passport: {
        ...passport,
        inventory: {},
        stash: nextStash,
      },
      depositedCount,
    };
  }

  /**
   * 將指定數量的單項道具從隨身背包存入中央客廳無限儲物箱
   */
  public static depositToStash(
    passport: SnekPetPassport,
    itemId: string,
    count: number = 1
  ): {
    success: boolean;
    passport: SnekPetPassport;
    reason?: string;
  } {
    const haveInBag = passport.inventory?.[itemId] || 0;
    const moveCount = Math.min(haveInBag, Math.max(1, Math.floor(count)));
    if (moveCount <= 0) {
      return {
        success: false,
        passport,
        reason: 'NOT_IN_BACKPACK',
      };
    }

    const nextInv = { ...(passport.inventory || {}) };
    nextInv[itemId] = haveInBag - moveCount;
    if (nextInv[itemId] <= 0) {
      delete nextInv[itemId];
    }

    const nextStash = { ...(passport.stash || {}) };
    nextStash[itemId] = (nextStash[itemId] || 0) + moveCount;

    return {
      success: true,
      passport: {
        ...passport,
        inventory: nextInv,
        stash: nextStash,
      },
    };
  }

  /**
   * 從中央客廳無限儲物箱取出道具至隨身九宮格背包（受 9 格上限限制）
   */
  public static withdrawFromStash(
    passport: SnekPetPassport,
    itemId: string,
    count: number = 1
  ): {
    success: boolean;
    passport: SnekPetPassport;
    reason?: string;
  } {
    const haveInStash = passport.stash?.[itemId] || 0;
    const req = Math.max(1, Math.floor(count));
    if (haveInStash < req) {
      return {
        success: false,
        passport,
        reason: 'NOT_IN_STASH',
      };
    }

    const curInBag = passport.inventory?.[itemId] || 0;
    const partialRem = curInBag % MAX_ITEM_STACK_PER_SLOT;
    const roomInCurrentSlot = partialRem > 0 ? MAX_ITEM_STACK_PER_SLOT - partialRem : 0;
    const remainderReq = Math.max(0, req - roomInCurrentSlot);
    const slotsNeeded = Math.ceil(remainderReq / MAX_ITEM_STACK_PER_SLOT);
    const availableEmptySlots = SnekInventoryService.getBackpackRemainingSpace(passport);

    if (availableEmptySlots < slotsNeeded) {
      return {
        success: false,
        passport,
        reason: 'BACKPACK_FULL',
      };
    }

    const nextStash = { ...(passport.stash || {}) };
    nextStash[itemId] = haveInStash - req;
    if (nextStash[itemId] <= 0) {
      delete nextStash[itemId];
    }

    const nextInv = { ...(passport.inventory || {}) };
    nextInv[itemId] = (nextInv[itemId] || 0) + req;

    return {
      success: true,
      passport: {
        ...passport,
        inventory: nextInv,
        stash: nextStash,
      },
    };
  }

  /**
   * 查詢家園可用總庫存（隨身背包 + 中央客廳無限儲物箱）
   */
  public static getTotalHomesteadItemCount(passport: SnekPetPassport, itemId: string): number {
    return (passport.inventory?.[itemId] || 0) + (passport.stash?.[itemId] || 0);
  }

  /**
   * 從家園庫存（優先扣儲物箱，再扣隨身背包）扣除指定數量的材料或生鮮食材
   */
  public static consumeHomesteadItem(
    passport: SnekPetPassport,
    itemId: string,
    requiredCount: number
  ): {
    success: boolean;
    passport: SnekPetPassport;
    reason?: string;
  } {
    const req = Math.max(0, Math.floor(requiredCount));
    if (req === 0) {
      return { success: true, passport };
    }

    const total = SnekInventoryService.getTotalHomesteadItemCount(passport, itemId);
    if (total < req) {
      return {
        success: false,
        passport,
        reason: 'INSUFFICIENT_ITEM',
      };
    }

    const nextStash = { ...(passport.stash || {}) };
    const nextInv = { ...(passport.inventory || {}) };

    let toDeduct = req;
    const fromStash = Math.min(nextStash[itemId] || 0, toDeduct);
    if (fromStash > 0) {
      nextStash[itemId] -= fromStash;
      if (nextStash[itemId] <= 0) delete nextStash[itemId];
      toDeduct -= fromStash;
    }

    if (toDeduct > 0) {
      nextInv[itemId] = (nextInv[itemId] || 0) - toDeduct;
      if (nextInv[itemId] <= 0) delete nextInv[itemId];
    }

    return {
      success: true,
      passport: {
        ...passport,
        inventory: nextInv,
        stash: nextStash,
      },
    };
  }

  /**
   * 計算強化武器至下一級所需的鍛造鐵礦數量
   */
  public static getUpgradeStoneCost(currentUpgradeLevel: number): number {
    return 1 + Math.floor(Math.max(0, currentUpgradeLevel) / 2);
  }

  /**
   * 戶外打鐵工坊嚴格強化武器：必須同時具備足夠金幣與鍛造鐵礦 (resource_stone)
   */
  public static upgradeWeaponWithMaterials(passport: SnekPetPassport): {
    success: boolean;
    passport: SnekPetPassport;
    goldCost: number;
    stoneCost: number;
    reason?: string;
  } {
    const currentLv = passport.equippedWeapon.upgradeLevel || 0;
    const goldCost = ArtisanForgeService.getUpgradeGoldCost(currentLv);
    const stoneCost = SnekInventoryService.getUpgradeStoneCost(currentLv);

    if (currentLv >= MAX_WEAPON_UPGRADE_LEVEL) {
      return {
        success: false,
        passport,
        goldCost: 0,
        stoneCost: 0,
        reason: 'MAX_LEVEL_REACHED',
      };
    }

    if (passport.wallet.gold < goldCost) {
      return {
        success: false,
        passport,
        goldCost,
        stoneCost,
        reason: 'INSUFFICIENT_GOLD',
      };
    }

    const totalStone = SnekInventoryService.getTotalHomesteadItemCount(passport, 'resource_stone');
    if (totalStone < stoneCost) {
      return {
        success: false,
        passport,
        goldCost,
        stoneCost,
        reason: 'INSUFFICIENT_MATERIAL',
      };
    }

    const consumed = SnekInventoryService.consumeHomesteadItem(
      passport,
      'resource_stone',
      stoneCost
    );
    const upgraded = ArtisanForgeService.upgradeWeapon(consumed.passport);

    return {
      success: upgraded.success,
      passport: upgraded.passport,
      goldCost,
      stoneCost,
      reason: upgraded.reason,
    };
  }

  /**
   * 檢查指定銃槍武器是否已解鎖
   */
  public static isWeaponUnlocked(passport: SnekPetPassport, weaponId: string): boolean {
    if (weaponId === 'blaster_tier_1') return true;
    const list = passport.unlockedWeapons || ['blaster_tier_1'];
    return list.includes(weaponId);
  }

  /**
   * 取得工坊應顯示的武器清單（僅顯示「已解鎖銃槍」+「下一把可研發銃槍」，避免初始塞滿太多武器）
   */
  public static getVisibleWorkshopWeapons(passport: SnekPetPassport): CraftableWeaponRecipe[] {
    const visible: CraftableWeaponRecipe[] = [];
    let addedLocked = false;
    for (const recipe of CRAFTABLE_WEAPONS_CATALOG) {
      if (SnekInventoryService.isWeaponUnlocked(passport, recipe.weaponId)) {
        visible.push(recipe);
      } else if (!addedLocked) {
        visible.push(recipe);
        addedLocked = true;
      }
    }
    return visible;
  }

  /**
   * 裝備已解鎖的武器（若尚未解鎖則拒絕換裝 WEAPON_LOCKED）
   */
  public static equipUnlockedWeapon(
    passport: SnekPetPassport,
    weaponId: string
  ): {
    success: boolean;
    passport: SnekPetPassport;
    reason?: string;
  } {
    const recipe = CRAFTABLE_WEAPONS_CATALOG.find((w) => w.weaponId === weaponId);
    if (!recipe) {
      return { success: false, passport, reason: 'UNKNOWN_WEAPON' };
    }

    if (!SnekInventoryService.isWeaponUnlocked(passport, weaponId)) {
      return { success: false, passport, reason: 'WEAPON_LOCKED' };
    }

    const nextSpec = recipe.buildSpec(
      passport.equippedWeapon.upgradeLevel,
      passport.equippedWeapon.enchantmentTags || []
    );

    return {
      success: true,
      passport: {
        ...passport,
        moodEmote: 'star',
        equippedWeapon: nextSpec,
      },
    };
  }

  /**
   * 在戶外打鐵工坊消耗「金幣 + 鍛造鐵礦 + 魔力水晶」鍛造解鎖新銃槍並立即裝備
   */
  public static craftAndUnlockWeapon(
    passport: SnekPetPassport,
    weaponId: string
  ): {
    success: boolean;
    passport: SnekPetPassport;
    reason?: string;
  } {
    const recipe = CRAFTABLE_WEAPONS_CATALOG.find((w) => w.weaponId === weaponId);
    if (!recipe) {
      return { success: false, passport, reason: 'UNKNOWN_WEAPON' };
    }

    if (SnekInventoryService.isWeaponUnlocked(passport, weaponId)) {
      return SnekInventoryService.equipUnlockedWeapon(passport, weaponId);
    }

    if (passport.wallet.gold < recipe.goldCost) {
      return { success: false, passport, reason: 'INSUFFICIENT_GOLD' };
    }

    if (
      SnekInventoryService.getTotalHomesteadItemCount(passport, 'resource_stone') < recipe.stoneCost
    ) {
      return { success: false, passport, reason: 'INSUFFICIENT_STONE' };
    }

    if (
      SnekInventoryService.getTotalHomesteadItemCount(passport, 'resource_crystal') <
      recipe.crystalCost
    ) {
      return { success: false, passport, reason: 'INSUFFICIENT_CRYSTAL' };
    }

    let next = SnekInventoryService.consumeHomesteadItem(
      passport,
      'resource_stone',
      recipe.stoneCost
    ).passport;
    next = SnekInventoryService.consumeHomesteadItem(
      next,
      'resource_crystal',
      recipe.crystalCost
    ).passport;

    const unlockedList = Array.from(
      new Set([...(next.unlockedWeapons || ['blaster_tier_1']), weaponId])
    );

    next = {
      ...next,
      wallet: {
        ...next.wallet,
        gold: next.wallet.gold - recipe.goldCost,
      },
      unlockedWeapons: unlockedList,
    };

    return SnekInventoryService.equipUnlockedWeapon(next, weaponId);
  }

  /**
   * 取得目前已解鎖的附魔魔法清單（初始為空，需領悟解鎖才會顯示）
   */
  public static getUnlockedEnchantments(passport: SnekPetPassport): WeaponEnchantmentTag[] {
    return passport.unlockedEnchantments || [];
  }

  /**
   * 消耗 1 顆魔力水晶瓶 (resource_crystal) + 80 金幣，領悟解鎖下一個附魔魔法
   */
  public static unlockNextEnchantment(passport: SnekPetPassport): {
    success: boolean;
    passport: SnekPetPassport;
    unlockedTag?: WeaponEnchantmentTag;
    reason?: string;
  } {
    const unlocked = SnekInventoryService.getUnlockedEnchantments(passport);
    const nextTag = ALL_ENCHANTMENT_ORDER.find((t) => !unlocked.includes(t));
    if (!nextTag) {
      return {
        success: false,
        passport,
        reason: 'ALL_ENCHANTMENTS_UNLOCKED',
      };
    }

    const goldCost = 80;
    if (passport.wallet.gold < goldCost) {
      return {
        success: false,
        passport,
        reason: 'INSUFFICIENT_GOLD',
      };
    }

    const haveCrystal = SnekInventoryService.getTotalHomesteadItemCount(
      passport,
      'resource_crystal'
    );
    if (haveCrystal < 1) {
      return {
        success: false,
        passport,
        reason: 'INSUFFICIENT_CRYSTAL',
      };
    }

    const consumed = SnekInventoryService.consumeHomesteadItem(passport, 'resource_crystal', 1);
    const updated: SnekPetPassport = {
      ...consumed.passport,
      moodEmote: 'idea',
      wallet: {
        ...consumed.passport.wallet,
        gold: consumed.passport.wallet.gold - goldCost,
      },
      unlockedEnchantments: [...unlocked, nextTag],
    };

    return {
      success: true,
      passport: updated,
      unlockedTag: nextTag,
    };
  }

  /**
   * 室內廚房烹飪台：將地下城打回來的「生鮮食材 (raw_*)」烹煮成「熟食料理道具 (dish_*)」放入背包/儲物箱
   * （不可直接在廚房吃！）
   */
  public static cookRecipeAtKitchen(
    passport: SnekPetPassport,
    dishId: string
  ): {
    success: boolean;
    passport: SnekPetPassport;
    placedIn: 'BACKPACK' | 'STASH';
    reason?: string;
  } {
    const recipe = KITCHEN_RECIPES.find((r) => r.dishId === dishId);
    if (!recipe) {
      return {
        success: false,
        passport,
        placedIn: 'BACKPACK',
        reason: 'UNKNOWN_RECIPE',
      };
    }

    const haveRaw = SnekInventoryService.getTotalHomesteadItemCount(
      passport,
      recipe.rawIngredientId
    );
    if (haveRaw < recipe.rawIngredientCount) {
      return {
        success: false,
        passport,
        placedIn: 'BACKPACK',
        reason: 'INSUFFICIENT_RAW_INGREDIENT',
      };
    }

    const afterConsume = SnekInventoryService.consumeHomesteadItem(
      passport,
      recipe.rawIngredientId,
      recipe.rawIngredientCount
    ).passport;

    // 優先放入隨身九宮格背包，若已滿 9 格則自動存入中央儲物箱
    const space = SnekInventoryService.getBackpackRemainingSpace(afterConsume);
    if (space >= 1) {
      const added = SnekInventoryService.addItemsToBackpack(afterConsume, { [dishId]: 1 });
      return {
        success: true,
        passport: added.passport,
        placedIn: 'BACKPACK',
      };
    } else {
      const nextStash = { ...(afterConsume.stash || {}) };
      nextStash[dishId] = (nextStash[dishId] || 0) + 1;
      return {
        success: true,
        passport: {
          ...afterConsume,
          stash: nextStash,
        },
        placedIn: 'STASH',
      };
    }
  }

  /**
   * 從隨身九宮格背包點擊「食用」已煮熟的料理道具 (dish_*)，永久提升五維與親密度
   */
  public static eatCookedDishFromBackpack(
    passport: SnekPetPassport,
    itemId: string
  ): {
    success: boolean;
    passport: SnekPetPassport;
    reason?: string;
  } {
    const entry = ITEM_CATALOG[itemId];
    if (!entry) {
      return { success: false, passport, reason: 'INVALID_ITEM' };
    }
    if (entry.category === 'RAW_INGREDIENT') {
      return {
        success: false,
        passport,
        reason: 'RAW_CANNOT_EAT_DIRECTLY',
      };
    }
    if (entry.category !== 'COOKED_DISH') {
      return {
        success: false,
        passport,
        reason: 'NOT_COOKED_DISH',
      };
    }

    const haveInBag = passport.inventory?.[itemId] || 0;
    if (haveInBag < 1) {
      return {
        success: false,
        passport,
        reason: 'NOT_IN_BACKPACK',
      };
    }

    const nextInv = { ...(passport.inventory || {}) };
    nextInv[itemId] = haveInBag - 1;
    if (nextInv[itemId] <= 0) {
      delete nextInv[itemId];
    }

    const fed = ArtisanForgeService.feedPet(
      {
        ...passport,
        inventory: nextInv,
      },
      entry.affectionGain || 8,
      entry.statBonus
    );

    return {
      success: true,
      passport: fed,
    };
  }
}
